"""Сколько ответов писателя несут невидимые знаки и сколько сверок цифр упали на эхе цифры."""

import json
import pathlib
import sys
import unicodedata

ODD = {" ", " ", " ", " ", " ", " ", "​", "‌", "‍", "⁠", "﻿"}

runs = pathlib.Path(sys.argv[1])
answers = with_odd = 0
values = odd_values = 0
odd_text = 0
examples: list[str] = []
for path in sorted(runs.glob("*/calls/story/story-?.json")):
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        continue
    answers += 1
    text = json.dumps(data.get("answer"), ensure_ascii=False)
    found = sorted({ch for ch in text if ch in ODD})
    if found:
        with_odd += 1
        odd_text += 1
    stack = [data.get("answer")]
    while stack:
        node = stack.pop()
        if isinstance(node, dict):
            for key, val in node.items():
                if key == "value" and isinstance(val, str):
                    values += 1
                    hits = [unicodedata.name(ch, hex(ord(ch))) for ch in val if ch in ODD]
                    if hits:
                        odd_values += 1
                        if len(examples) < 12:
                            examples.append(f"{path.parent.parent.parent.name}/{path.name}: {val!r} {hits}")
                else:
                    stack.append(val)
        elif isinstance(node, list):
            stack.extend(node)
print(f"ответов писателя {answers}, с невидимыми знаками где-либо {with_odd}")
print(f"цифр карточек {values}, с невидимыми знаками {odd_values}")
for line in examples:
    print("  ", line)

fails = 0
echo_fails = 0
for path in sorted(runs.glob("*/calls/story/story-?-check.invalid.txt")):
    fails += 1
print(f"отвергнутых ответов сверщика (invalid) {fails}")

