_SENTENCE_BREAK = re.compile(r"(?<=[.!?…])\s+(?=[А-ЯA-ZЁ])")
_TABLE_DIVIDER = re.compile(r"[\s|:\-]+")
_CELL_SEPARATOR = re.compile(r"(?<!\\)(?:\\\\)*\|")


def _usable(place: str) -> bool:
    return significant_length(place) >= MIN_ANCHOR_LENGTH and not _TABLE_DIVIDER.fullmatch(place)


def _cells(line: str) -> list[str]:
    # Отделяем настоящие границы ячеек, не экранированную черту внутри текста.
    cells = _CELL_SEPARATOR.split(line)
    if line.startswith("|"):
        cells = cells[1:]
    if line.endswith("|"):
        cells = cells[:-1]
    return [cell.strip() for cell in cells]


def _sentences(line: str) -> list[str]:
    sentences = [sentence.strip() for sentence in _SENTENCE_BREAK.split(line) if sentence.strip()]
    places = [sentence for sentence in sentences if _usable(sentence)]
    for sentence in sentences:
        pieces = [piece.strip() for piece in re.split(r";\s+|,\s+(?=\d)", sentence)]
        if len(pieces) > 1:
            places.extend(piece for piece in pieces if _usable(piece))
    return list(dict.fromkeys(places))


def numbered_places(source: str) -> list[list[str]]:
    """Дословные кандидаты для каждой строки поста, в порядке, видимом сверщику."""
    lines = source.splitlines()
    result: list[list[str]] = []
    header: list[str] | None = None
    for number, line in enumerate(lines):
        cells = _cells(line) if line.strip().startswith("|") else []
        if cells and _TABLE_DIVIDER.fullmatch(line):
            result.append([])
            header = _cells(lines[number - 1]) if number else None
            continue
        if cells and header is not None:
            row_label = cells[0]
            places: list[str] = []
            for index, cell in enumerate(cells[1:], 1):
                if not cell or index >= len(header):
                    continue
                place = " … ".join(part for part in (header[index], row_label, cell) if part)
                if _usable(place):
                    places.append(place)
            result.append(places or ([line] if _usable(line) else []))
        else:
            header = None
            result.append(_sentences(line))
    return result


def figure_places(answer: FigureVerdicts, source: str) -> dict[int, str]:
    """Взять выбранный фрагмент исходного поста, без нумерации (FR-14)."""
    lines = numbered_places(source)
    places: dict[int, str] = {}
    for verdict in answer.verdicts:
        number, fragment = verdict.line_number, verdict.fragment_number
        if not verdict.in_post or number is None or not 1 <= number <= len(lines):
            continue
        candidates = lines[number - 1]
        if fragment is not None and 1 <= fragment <= len(candidates):
            places[verdict.card] = candidates[fragment - 1]
    return places

