"""Размеченный случай калибровки: смысл оценивает человек, код связывает доказательства."""

from __future__ import annotations

from pathlib import PurePosixPath
from typing import Literal, Self

from pydantic import Field, field_validator, model_validator

from carousel.schemas import Contract, Sha256, Text

Criterion = Literal[
    "evidence_found", "main_idea_proposed", "main_idea_selected", "cards_faithful", "ranking"
]
Verdict = Literal["passed", "failed", "not-applicable", "unlabelled"]
REQUIRED_ARTIFACTS = frozenset({
    "post.json", "analysis.json", "meta/analyze.json", "meta/story.json",
    "moves_selected.json", "stories/A.json", "stories/B.json", "stories/C.json",
})


class CalibrationRefused(Exception):
    """Случай нельзя привязать к проверяемому выходу графа."""


def artifact_path(value: str) -> str:
    path = PurePosixPath(value)
    if path.is_absolute() or ".." in path.parts or "\\" in value or ":" in value:
        raise ValueError("путь артефакта должен быть относительным внутри прогона")
    return value


class Evidence(Contract):
    file: Text
    quote: Text


class Label(Contract):
    criterion: Criterion
    value: Verdict
    by: Literal["author", "assistant"]
    reason: Text
    evidence: list[Evidence] = Field(min_length=1)
    reference: Evidence


class CalibrationCase(Contract):
    id: Text
    criteria: dict[Criterion, Text] = Field(min_length=1)
    config_sha256: Sha256
    artifacts: dict[str, Sha256]
    source_trace_id: str = Field(pattern=r"^[a-f0-9]{32}$")
    source_observation_ids: list[str] = Field(min_length=1)
    labels: list[Label] = Field(min_length=1)

    @field_validator("id")
    @classmethod
    def _safe_id(cls, value: str) -> str:
        if not value or any(char not in "abcdefghijklmnopqrstuvwxyz0123456789-_" for char in value):
            raise ValueError("id случая: строчные латинские буквы, цифры, дефис и подчёркивание")
        return value

    @field_validator("artifacts")
    @classmethod
    def _source_artifacts(cls, value: dict[str, str]) -> dict[str, str]:
        for name in value:
            artifact_path(name)
        if not REQUIRED_ARTIFACTS.issubset(value):
            raise ValueError("нужны post, analysis, meta analyze/story, moves_selected и истории A/B/C")
        return value

    @field_validator("source_observation_ids")
    @classmethod
    def _span_ids(cls, value: list[str]) -> list[str]:
        if len(value) != len(set(value)) or any(
            len(item) != 16 or any(char not in "abcdef0123456789" for char in item) for item in value
        ):
            raise ValueError("observation IDs: уникальные шестнадцатеричные строки длиной 16")
        return value

    @model_validator(mode="after")
    def _labels_are_bound(self) -> Self:
        keys = [(label.criterion, label.by) for label in self.labels]
        if len(keys) != len(set(keys)):
            raise ValueError("дубли оценок одного критерия и источника")
        for label in self.labels:
            if label.criterion not in self.criteria:
                raise ValueError("для оценки нужен критерий")
            for evidence in label.evidence:
                artifact_path(evidence.file)
                if evidence.file not in self.artifacts:
                    raise ValueError("цитата должна ссылаться на хешированный артефакт")
        return self

    def scores(self) -> dict[str, str]:
        return {f"{label.criterion}.{label.by}": label.value for label in self.labels}

