from __future__ import annotations

import json
from collections.abc import Mapping
from datetime import datetime
from hashlib import sha256
from pathlib import Path
from typing import Any

from langfuse import Evaluation, Langfuse

from carousel.calibrate import CalibrationCase, CalibrationRefused
from carousel.nodes.rundir import file_sha256, read_model, write_atomic
from carousel.observability import Telemetry, _export_allowed
from carousel.schemas import Analysis, PostDoc
from carousel.story import Story
from carousel.trace import StepMeta


def _dump(path: Path, value: Any) -> None:
    write_atomic(path, (json.dumps(value, ensure_ascii=False, indent=2) + "\n").encode("utf-8"))


def _has_quote(value: Any, quote: str) -> bool:
    if isinstance(value, str):
        return quote in value
    if isinstance(value, dict):
        return any(_has_quote(item, quote) for item in value.values())
    if isinstance(value, list):
        return any(_has_quote(item, quote) for item in value)
    return False


def _read_artifacts(run: Path, case: CalibrationCase) -> dict[str, Any]:
    artifacts = {}
    for name, expected in case.artifacts.items():
        path = (run / name).resolve()
        if not path.is_relative_to(run.resolve()) or not path.is_file():
            raise CalibrationRefused(f"артефакт недоступен внутри прогона: {name}")
        if file_sha256(path) != expected:
            raise CalibrationRefused(f"хеш артефакта изменился: {name}")
        artifacts[name] = json.loads(path.read_bytes())
    read_model(run / "post.json", PostDoc)
    read_model(run / "analysis.json", Analysis)
    for letter in "ABC":
        read_model(run / f"stories/{letter}.json", Story)
    for step in ("analyze", "story"):
        read_model(run / f"meta/{step}.json", StepMeta)
    for label in case.labels:
        for evidence in label.evidence:
            if not _has_quote(artifacts[evidence.file], evidence.quote):
                raise CalibrationRefused(f"цитата отсутствует в артефакте: {evidence.file}")
        reference = Path(label.reference.file)
        if not reference.is_file() or label.reference.quote not in reference.read_text(encoding="utf-8"):
            raise CalibrationRefused("цитата правила отсутствует в указанном источнике")
    return artifacts


def _json(value: Any) -> Any:
    return json.loads(value) if isinstance(value, str) else value


def export_recorded(
    client: Any, case: CalibrationCase, manifest: dict[str, Any], at: datetime
) -> dict[str, Any]:
    """Task возвращает только записанный выход, evaluator переносит явно подписанные метки."""
    session = manifest["session_id"]
    observations, cursor = [], None
    while True:
        page = client.api.observations.get_many(
            session_id=session, trace_id=case.source_trace_id, limit=100, cursor=cursor,
            fields="core,basic,io,metadata",
        )
        observations.extend(page.data)
        cursor = getattr(page.meta, "cursor", None)
        if not cursor or not page.data:
            break
    ids = {item.id for item in observations if item.trace_id == case.source_trace_id}
    if not set(case.source_observation_ids).issubset(ids):
        raise CalibrationRefused("исходная trace/observations не найдены в сессии прогона")
    dataset_name = "carousel/main-idea-recorded"
    client.create_dataset(name=dataset_name, description="Размеченные выходы графа, без генерации")
    item = client.create_dataset_item(
        dataset_name=dataset_name,
        id=f"{case.id}-{manifest['case_sha256'][:12]}",
        input=manifest["input"], expected_output=case.criteria,
        metadata={"case_sha256": manifest["case_sha256"], "group": manifest["input"]["post"]["url"]},
        source_trace_id=case.source_trace_id,
        source_observation_id=case.source_observation_ids[0],
    )
    dataset = client.get_dataset(dataset_name)
    selected = [entry for entry in dataset.items if entry.id == item.id]
    if len(selected) != 1:
        raise CalibrationRefused("записанный Dataset item не прочитан")

    def task(*, item: Any, **kwargs: Any) -> Any:
        return manifest["output"]

    def evaluate(**kwargs: Any) -> list[Evaluation]:
        return [Evaluation(
            name=f"{label.criterion}.{label.by}", value=label.value, data_type="CATEGORICAL",
            comment=label.reason, metadata=label.model_dump(mode="json"),
        ) for label in case.labels]

    result = client.run_experiment(
        name=dataset_name, run_name=f"{case.id}-{at.isoformat()}", data=selected,
        task=task, evaluators=[evaluate], max_concurrency=1,
        metadata={"source": "recorded", "run": manifest["run"], "case_sha256": manifest["case_sha256"]},
    )
    item_result = result.item_results[0]
    client.flush()
    read_scores = client.api.scores.get_many(trace_id=item_result.trace_id, limit=100)
    scores = {entry.name: entry.string_value for entry in read_scores.data}
    read_output = client.api.observations.get_many(
        trace_id=item_result.trace_id, fields="core,basic,io", limit=100,
    )
    if any(scores.get(name) != value for name, value in case.scores().items()) or not any(
        _json(entry.output) == manifest["output"] for entry in read_output.data
    ):
        raise CalibrationRefused("readback experiment output/scores не подтверждён")
    return {
        "status": "passed", "dataset": dataset_name, "dataset_item": item.id,
        "dataset_version": at.isoformat(), "experiment_id": result.experiment_id,
        "trace_id": item_result.trace_id, "url": result.experiment_url,
        "source_observation_ids": sorted(ids), "scores": scores,
    }


def _export(case: CalibrationCase, manifest: dict[str, Any], environ: Mapping[str, str], at: datetime) -> dict[str, Any]:
    url = environ.get("LANGFUSE_BASE_URL", "")
    if not _export_allowed(url) or not all(environ.get(name) for name in ("LANGFUSE_PUBLIC_KEY", "LANGFUSE_SECRET_KEY")):
        return {"status": "skipped", "reason": "нужны центральный Langfuse и оба ключа"}
    client = None
    try:
        telemetry = Telemetry(None, [environ["LANGFUSE_SECRET_KEY"]], environ["LANGFUSE_PUBLIC_KEY"])
        client = Langfuse(
            base_url=url, public_key=environ["LANGFUSE_PUBLIC_KEY"], secret_key=environ["LANGFUSE_SECRET_KEY"],
            mask=telemetry.clean, mask_otel_spans=telemetry.mask,
        )
        return export_recorded(client, case, manifest, at)
    except Exception as error:
        reason = str(error) if isinstance(error, CalibrationRefused) else f"Langfuse: {type(error).__name__}"
        return {"status": "skipped", "reason": reason}
    finally:
        if client is not None:
            client.shutdown()


def record_calibration(
    run: Path, case_path: Path, config: Path, output: Path,
