"""Парное сравнение двух прогонов одного поста вслепую (US-32, ARCHITECTURE §5).

Ядро: направления двух прогонов, порядок, ключ и страница. Чтение прогонов и запись файлов — в
`carousel/nodes/compare.py`. Макеты карточек те же, что на `texts.html`; имён прогонов, стоимости
и вердикта судьи на странице нет, порядок вариантов случайный и свой у каждого направления.
"""

from __future__ import annotations

import random
from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from html import escape

from carousel.plan import Plan
from carousel.schemas import SLOT_LETTERS, Contract, Letter
from carousel.story import Story
from carousel.texts_html import STYLE, figures, summary

COMPARE_DIR = "_compare"  # в папке прогонов: страница принадлежит паре прогонов
COMPARE_HTML = "compare.html"
KEY_JSON = "key.json"

PAIR_STYLE = """\
.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;align-items:start}
.pair .cards{gap:14px}
.pair figure{width:calc(50% - 7px)}
h3{font-size:18px;margin:10px 0 4px}
"""


class ComparisonRefused(ValueError):
    """Пару прогонов нельзя сравнить. Текст читает автор."""


@dataclass(frozen=True)
class Side:
    """Направление одного прогона: ход, план и история слота."""

    move: str
    plan: Plan
    story: Story


@dataclass(frozen=True)
class Candidate:
    """Прогон для сравнения: имя, пост и направления по буквам слотов."""

    run: str
    url: str
    title: str
    sides: Mapping[Letter, Side]


class CompareKey(Contract):
    """`key.json`: какой прогон стоит под «Вариантом 1» и «Вариантом 2» в каждом направлении."""

    url: str
    directions: dict[Letter, list[str]]


@dataclass(frozen=True)
class Shown:
    """Прогон и его направление так, как их показывает страница."""

    run: str
    side: Side


@dataclass(frozen=True)
class Pairing:
    """Пара прогонов, разложенная по направлениям в показанном порядке."""

    title: str
    url: str
    directions: Mapping[Letter, tuple[Shown, Shown]]

    def key(self) -> CompareKey:
        return CompareKey(
            url=self.url,
            directions={
                letter: [left.run, right.run] for letter, (left, right) in self.directions.items()
            },
        )

    def html(self) -> str:
        """Страница: заголовок поста, затем блок на направление с двумя столбцами."""
        title = escape(self.title)
        blocks = "".join(
            _direction(letter, left, right) for letter, (left, right) in self.directions.items()
        )
        return (
            '<!doctype html><html lang="ru"><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width, initial-scale=1">'
            f"<title>Два варианта вслепую · {title}</title>"
            f"<style>{STYLE}{PAIR_STYLE}</style><body><h1>Два варианта вслепую</h1>"
            f'<p class="note">Пост: {title}. Порядок вариантов случайный и свой у каждого '
            "направления: какой прогон под каким номером, страница не говорит. Карточки — макеты "
            "без картинок: читайте слова.</p>"
            f"{blocks}</body></html>"
        )


def flips_for(letters: Sequence[Letter], seed: str) -> dict[Letter, bool]:
    """Монета на каждое направление: `True` меняет прогоны местами. Зерно приходит снаружи, это
    момент запуска команды: тот же момент даёт тот же порядок."""
    coin = random.Random(seed)
    return {letter: coin.random() < 0.5 for letter in letters}


def pair(first: Candidate, second: Candidate, flips: Mapping[Letter, bool]) -> Pairing:
    """Прогоны одного поста с одним набором направлений, разложенные по монетам `flips`."""
    if first.url != second.url:
        raise ComparisonRefused(
            f"посты разные: у {first.run} {first.url}, у {second.run} {second.url}"
        )
    if first.sides.keys() != second.sides.keys():
        raise ComparisonRefused(
            f"направления разные: у {first.run} {_letters(first)}, у {second.run} {_letters(second)}"
        )
    first_shown, second_shown = Shown, Shown
    directions: dict[Letter, tuple[Shown, Shown]] = {}
    for letter in sorted(first.sides, key=SLOT_LETTERS.index):
        left = first_shown(first.run, first.sides[letter])
        right = second_shown(second.run, second.sides[letter])
        directions[letter] = (right, left) if flips[letter] else (left, right)
    return Pairing(first.title, first.url, directions)


def _letters(candidate: Candidate) -> str:
    return ", ".join(sorted(candidate.sides, key=SLOT_LETTERS.index))


def _direction(letter: Letter, left: Shown, right: Shown) -> str:
    same = left.side.move == right.side.move
    move = f"<p>Ход: {escape(left.side.move)}</p>" if same else ""
    columns = "".join(
        _column(number, shown, with_move=not same) for number, shown in enumerate((left, right), 1)
    )
    return (
        f'<section><h2>Направление {escape(letter)}</h2>{move}<div class="pair">{columns}</div>'
        "</section>"
    )


def _column(number: int, shown: Shown, *, with_move: bool) -> str:
    side = shown.side
    move = f"<p>Ход: {escape(side.move)}</p>" if with_move else ""
    return (
        f"<div><h3>Вариант {number}</h3>{move}{summary(side.plan, side.story)}"
        f'<div class="cards">{figures(side.plan, side.story)}</div></div>'
    )

