"""Бриф перед писателем: что меняет решение читателя и на чём это стоит в посте (DR-13).

Ядро без инфраструктуры. Шаг brief (`carousel/nodes/brief.py`) просит модель написать `Brief`
по посту, а писатель при `[variants] story_input = "brief"` читает его вместо поста
(ARCHITECTURE §3, «Узел brief»).
"""

from __future__ import annotations

import tomllib
from collections.abc import Iterator
from pathlib import Path
from typing import Literal, Self

from pydantic import model_validator

from carousel.schemas import (
    Contract,
    PostDoc,
    Problem,
    Text,
    anchor_problems,
    require_grounded,
)

StoryInput = Literal["post", "brief"]  # вход писателя, ключ `[variants] story_input`
MIN_DECISIONS = 3
MAX_DECISIONS = 5
MAX_FACTS = 4  # фактов под одним решением
MAX_STAYS = 6


class Landscape(Contract):
    """Актуальные модели по разработчикам (`brand/landscape.toml`). Список ведёт автор: мерки
    сравнения берутся только из него, устаревшая модель читателю ничего не говорит."""

    current: dict[str, list[Text]]

    @model_validator(mode="after")
    def _names_models(self) -> Self:
        if not self.models():
            raise ValueError("в списке актуальных моделей нет ни одной модели")
        return self

    def models(self) -> list[str]:
        return [name for names in self.current.values() for name in names]

    def line(self) -> str:
        """Список для задания модели: разработчик и его модели, разработчики через «;»."""
        return "; ".join(
            f"{maker}: {', '.join(names)}" for maker, names in self.current.items() if names
        )


def load_landscape(path: Path) -> Landscape:
    try:
        return Landscape.model_validate(tomllib.loads(path.read_text(encoding="utf-8")))
    except (OSError, ValueError) as error:  # TOMLDecodeError и ValidationError — ValueError
        raise ValueError(
            f"список актуальных моделей {path.as_posix()} не прочитан: {error}"
        ) from error


class BriefFact(Contract):
    """Факт брифа. `text` — слова автора, готовые лечь на карточку: от первого лица там, где пост
    говорит о действии автора, с условием в том же предложении и без пометок источника.
    `anchor` — кусок поста дословно, на котором стоит факт; писатель его не видит."""

    text: Text
    anchor: Text


class Decision(Contract):
    """Решение читателя вопросом без «я» и факты, которые на него отвечают."""

    question: Text
    facts: list[BriefFact]

    @model_validator(mode="after")
    def _is_a_question_with_facts(self) -> Self:
        if not self.question.rstrip().endswith("?"):
            raise ValueError(f"решение читателя — вопрос, знака вопроса нет: {self.question!r}")
        if not 1 <= len(self.facts) <= MAX_FACTS:
            raise ValueError(
                f"под решением {self.question!r} фактов {len(self.facts)}, "
                f"нужно от 1 до {MAX_FACTS}"
            )
        return self


class Brief(Contract):
    """Что читатель решит иначе, узнав пост: ведущее утверждение, решения с фактами, что остаётся
    в посте, причина открыть пост и мерки сравнения из списка актуальных моделей (DR-13)."""

    claim: BriefFact
    decisions: list[Decision]
    stays: list[BriefFact]
    finale: BriefFact
    measures: list[Text]

    @model_validator(mode="after")
    def _has_the_shape(self) -> Self:
        if not MIN_DECISIONS <= len(self.decisions) <= MAX_DECISIONS:
            raise ValueError(
                f"решений читателя {len(self.decisions)}, нужно от {MIN_DECISIONS} до {MAX_DECISIONS}"
            )
        if len(self.stays) > MAX_STAYS:
            raise ValueError(
                f"в «остаётся в посте» {len(self.stays)} пунктов, нужно не больше {MAX_STAYS}"
            )
        return self

    def anchors(self) -> Iterator[tuple[str, str]]:
        """Путь к якорю и сам якорь: каждый должен стоять в посте дословно (CR-07, FR-14)."""
        yield "claim.anchor", self.claim.anchor
        for number, decision in enumerate(self.decisions):
            for index, fact in enumerate(decision.facts):
                yield f"decisions[{number}].facts[{index}].anchor", fact.anchor
        for number, fact in enumerate(self.stays):
            yield f"stays[{number}].anchor", fact.anchor
        yield "finale.anchor", self.finale.anchor

    def problems(self, post: PostDoc) -> list[Problem]:
        """Якоря дословно есть в посте и не короче минимума."""
        return anchor_problems(post.to_markdown(), self.anchors())

    def for_writer(self) -> str:
        """Бриф в том виде, как его видит писатель: слова фактов, без якорей. Пометке источника
        негде попасть на карточку."""
        lines = [f"Главное: {self.claim.text}", "", "Решения читателя:"]
        for number, decision in enumerate(self.decisions, 1):
            lines.append(f"{number}. {decision.question}")
            lines += [f"   - {fact.text}" for fact in decision.facts]
        if self.measures:
            lines += ["", f"Мерки сравнения: {', '.join(self.measures)}"]
        if self.stays:
            lines += ["", "Остаётся в посте:", *(f"- {fact.text}" for fact in self.stays)]
        lines += ["", f"Финал: {self.finale.text}"]
        return "\n".join(lines)

    @classmethod
    def bound_to(cls, post: PostDoc, landscape: Landscape) -> type[Self]:
        """Схема ответа для этого поста: якоря дословно из него, мерки из списка актуальных
        моделей и каждая не больше одного раза."""

        class Bound(cls):  # type: ignore[valid-type, misc]
            __doc__ = cls.__doc__

            @model_validator(mode="after")
            def _stands_on_the_post(self) -> Self:
                require_grounded(self.problems(post), "бриф")
                return self

            @model_validator(mode="after")
            def _measures_are_current(self) -> Self:
                current = set(landscape.models())
                foreign = [name for name in self.measures if name not in current]
                if foreign:
                    raise ValueError(
                        f"мерки вне списка актуальных моделей: {', '.join(foreign)}"
                    )
                if len(set(self.measures)) != len(self.measures):
                    raise ValueError(f"мерки сравнения повторяются: {', '.join(self.measures)}")
                return self

        Bound.__name__ = Bound.__qualname__ = cls.__name__
        return Bound


class BriefFile(Contract):
    """`brief.json`: бриф или причина, по которой шаг его не строил."""

    brief: Brief | None = None
    skipped: Text | None = None

    @model_validator(mode="after")
    def _holds_one_of_them(self) -> Self:
        if (self.brief is None) == (self.skipped is None):
            raise ValueError("в файле брифа либо бриф, либо причина, по которой его нет")
        return self

import glob
import re

for p in sorted(glob.glob("runs/20261018-*/stories/*.md")):
    run = p.replace("\\", "/").split("/")[1]
    if run.endswith(("-b", "-b2")):
        continue
    t = open(p, encoding="utf-8").read()
    bad = []
    for i, ch in enumerate(t):
        if ch in "ëË":
            bad.append(("latin-e-diaeresis", t[max(0, i - 12) : i + 8].replace("\n", " ")))
    for m in re.finditer(r"[A-Za-z][Ѐ-ӿ]+|[Ѐ-ӿ]+[A-Za-z](?![A-Za-z])", t):
        bad.append(("mixed", m.group(0)))
    if re.search(r"\\u[0-9a-fA-F]{4}", t):
        bad.append(("backslash-u", "x"))
    if bad:
        print(run[-45:], p.replace("\\", "/")[-6:], len(bad), bad[:8])

"""Сверка цифр карточек с постом: ответ сверщика → расхождения для писателя и места цифр в посте.

CR-07, FR-14; ARCHITECTURE §3, «Узел story».
"""

from __future__ import annotations

from carousel.checks.quotes import normalize
from carousel.figures import (
    FIGURE_ROUNDS,
    FigureOnCard,
    FigureVerdict,
    FigureVerdicts,
    figure_places,
    figure_problems,
)

SOURCE = normalize(
    "На Sonnet 4.5 этот объём стоил бы $3 790, а на DeepSeek — $4. Cache Read даёт 95,3% счёта."
)
PLACE = "На Sonnet 4.5 этот объём стоил бы $3 790, а на DeepSeek — $4."


def on_card(card: int, value: str, title: str = "Счёт") -> FigureOnCard:
    return FigureOnCard(card=card, value=value, label="подпись цифры", title=title)


def verdict(
    card: int, figure: str, *, in_post: bool = True, where: str = "", post_says: str = ""
) -> FigureVerdict:
    return FigureVerdict(
        card=card, figure=figure, in_post=in_post, where=where, post_says=post_says
    )


def test_cr07_the_writer_gets_two_rounds_to_fix_a_figure() -> None:
    assert FIGURE_ROUNDS == 2


def test_cr07_a_figure_the_checker_found_in_the_post_is_no_problem() -> None:
    figures = [on_card(1, "$3790")]
    answer = FigureVerdicts(verdicts=[verdict(1, "$3790", where=PLACE)])

    assert figure_problems(figures, answer) == []


def test_cr07_a_figure_the_checker_did_not_find_names_the_card_the_figure_and_what_the_post_says(
) -> None:
    figures = [on_card(2, "5,6 сек", title="Скорость")]
    answer = FigureVerdicts(
        verdicts=[verdict(2, "5,6 сек", in_post=False, post_says="В посте только 95,3% счёта.")]
    )

    problems = figure_problems(figures, answer)

    assert len(problems) == 1
    assert "карточка 2" in problems[0] and "Скорость" in problems[0] and "5,6 сек" in problems[0]
    assert "В посте только 95,3% счёта." in problems[0]


def test_cr07_a_figure_the_checker_did_not_find_while_the_post_is_silent_says_so() -> None:
    figures = [on_card(1, "99%")]
    answer = FigureVerdicts(verdicts=[verdict(1, "99%", in_post=False)])

    (problem,) = figure_problems(figures, answer)

    assert "99%" in problem and "пост об этом молчит" in problem


def test_cr07_a_figure_the_checker_skipped_is_a_problem_and_not_a_pass() -> None:
    figures = [on_card(1, "$3790"), on_card(4, "95,3%")]
    answer = FigureVerdicts(verdicts=[verdict(1, "$3790", where=PLACE)])

    (problem,) = figure_problems(figures, answer)

    assert "карточка 4" in problem and "95,3%" in problem and "не ответила" in problem


def test_fr14_the_place_of_a_found_figure_is_the_fragment_that_stands_in_the_post() -> None:
    answer = FigureVerdicts(verdicts=[verdict(1, "$3790", where=PLACE)])

    assert figure_places(answer, SOURCE) == {1: PLACE}


def test_fr14_a_fragment_the_post_does_not_have_is_not_a_place() -> None:
    answer = FigureVerdicts(
        verdicts=[verdict(1, "$3790", where="На Sonnet 4.5 этот объём стоил бы $3790")]
    )

    assert figure_places(answer, SOURCE) == {}


def test_fr14_a_fragment_shorter_than_an_anchor_is_not_a_place() -> None:
    answer = FigureVerdicts(verdicts=[verdict(1, "$4", where="$4.")])

    assert figure_places(answer, SOURCE) == {}


def test_fr14_a_figure_the_checker_did_not_find_has_no_place() -> None:
    answer = FigureVerdicts(
        verdicts=[verdict(1, "99%", in_post=False, where=PLACE, post_says="молчит")]
    )

    assert figure_places(answer, SOURCE) == {}

