async def _limit_response(self, response: httpx2.Response) -> None:
    declared = response.headers.get("content-length", "")
    if declared.isdigit() and int(declared) > self._max_response_bytes:
        await response.aclose()
        raise _ResponseLimit
    if response.is_stream_consumed:
        if len(response.content) > self._max_response_bytes:
            raise _ResponseLimit
        return
    # Декодированный поток оборачивается до чтения SDK, включая error responses.
    source = httpx2.Response(
        response.status_code, headers=response.headers, stream=response.stream
    )
    response.stream = _LimitedBody(source, self._max_response_bytes)
    response.headers.pop("content-encoding", None)

@asynccontextmanager
