async def _chat_stream(
    self, response: httpx2.Response, envelope: dict[str, Any]
) -> bool:
    """SSE декодирует SDK; текст и reasoning накапливает его готовое состояние."""
    state: ChatCompletionStreamState[Any] = ChatCompletionStreamState()
    seen = False
    done = False
    async for event in SSEDecoder().aiter_bytes(response.aiter_bytes()):
        if event.data.strip() == "[DONE]":
            done = True
            break
        try:
            data = event.json()
        except ValueError:
            envelope.clear()
            return False
        if not isinstance(data, dict):
            envelope.clear()
            return False
        seen = True
        if isinstance(data.get("usage"), dict):
            envelope["usage"] = data["usage"]
        if not envelope.get("model") and data.get("model"):
            envelope["model"] = data["model"]
        fail = partial(
            self._failure,
            response.request.url.path,  # заменяется контекстом вызова ниже
            usage=_usage(envelope.get("usage")),
            answered_model=_echoed_model(envelope),
        )
        # Ошибку проверяет общий договор чата после чтения накопленного расхода.
        if data.get("error"):
            envelope["error"] = data["error"]
            return True
        choices = data.get("choices")
        if not isinstance(choices, list):
            continue
        for choice in choices:
            if not isinstance(choice, dict):
                envelope.clear()
                return False
            choice.setdefault("delta", {})
            if choice.get("native_finish_reason"):
                envelope["native_finish_reason"] = choice["native_finish_reason"]
        chunk = ChatCompletionChunk.construct(**data)
        try:
            state.handle_chunk(chunk)
        except (AttributeError, IndexError, TypeError, ValueError):
            envelope.clear()
            return False
        snapshot = state.current_completion_snapshot
        if snapshot.choices:
            envelope["choices"] = [choice.to_dict() for choice in snapshot.choices]
    if not seen:
        envelope.clear()
    choices = envelope.get("choices") or []
    if choices and envelope.get("native_finish_reason"):
        choices[0]["native_finish_reason"] = envelope["native_finish_reason"]
    return done or bool(choices and choices[0].get("finish_reason"))

