@dataclass
class Observation:
    span: Any = None
    telemetry: Telemetry | None = None

    def update(self, **values: Any) -> None:
        if self.span is not None:
            try:
                self.span.update(**self.telemetry.clean(values) if self.telemetry else values)
            except Exception:
                _LOG.warning("Langfuse: наблюдение не обновлено")


class Telemetry:
    def __init__(self, client: Langfuse, secrets: Sequence[str], public_key: str | None) -> None:
        self.client = client
        self.secrets = tuple(value for value in secrets if value)
        self.public_key = public_key

    def clean(self, value: Any) -> Any:
        if isinstance(value, str):
            import json

            for secret in self.secrets:
                for form in (secret, json.dumps(secret)[1:-1], secret.replace("/", "\\/")):
                    value = value.replace(form, "[REDACTED]")
            return value
        if isinstance(value, Mapping):
            return {self.clean(key): self.clean(item) for key, item in value.items()}
        if isinstance(value, (tuple, list)):
            return [self.clean(item) for item in value]
        return value

    def mask(self, *, params: MaskOtelSpansParams) -> MaskOtelSpansResult:
        return MaskOtelSpansResult(
            span_patches={
                identifier: OtelSpanPatch(set_attributes=self.clean(dict(span.attributes)))
                for identifier, span in params.spans.items()
            }
        )


@contextmanager
def tracing(
    environ: Mapping[str, str],
    *,
    client: Langfuse | None = None,
    run_dir: Path | None = None,
    command: str = "run",
    secrets: Sequence[str] = (),
) -> Iterator[None]:
    owned = client is None
    keys = ("AIPOMOGATOR_TOKEN", "AIPOMOGATOR_API_KEY", "LANGFUSE_SECRET_KEY")
    all_secrets = (*secrets, *(environ.get(key, "") for key in keys))
    public_key = environ.get("LANGFUSE_PUBLIC_KEY")
    if client is None:
        url = environ.get("LANGFUSE_BASE_URL", "")
        if not url and not public_key and not environ.get("LANGFUSE_SECRET_KEY"):
            yield
            return
        if not _local(url) or not public_key or not environ.get("LANGFUSE_SECRET_KEY"):
            _LOG.warning("Langfuse: экспорт выключен, нужны локальный адрес и оба ключа")
            yield
            return
        try:
            # Штатный masking привязывается к клиенту до первого наблюдения.
            telemetry = Telemetry(None, all_secrets, public_key)  # type: ignore[arg-type]
            client = Langfuse(
                public_key=public_key,
                secret_key=environ["LANGFUSE_SECRET_KEY"],
                base_url=url,
                mask=telemetry.clean,
                mask_otel_spans=telemetry.mask,
            )
            telemetry.client = client
        except Exception:
            _LOG.warning("Langfuse: клиент не создан, трасса не отправлена")
            yield
            return
    else:
        # CallbackHandler требует явный ключ при нескольких клиентах в одном процессе.
        public_key = public_key or client._resources.public_key if client._resources else public_key
        telemetry = Telemetry(client, all_secrets, public_key)
    token = _CURRENT.set(telemetry)
    try:
        if run_dir is None:
            yield
        else:
            with graph_execution(run_dir, command):
                yield
    finally:
        _CURRENT.reset(token)
        if owned:
            try:
                client.shutdown()
            except Exception:
                _LOG.warning("Langfuse: завершение отправки не подтверждено")


@contextmanager
def observation(name: str, *, as_type: str = "generation", **values: Any) -> Iterator[Observation]:
    telemetry = _CURRENT.get()
    if telemetry is None:
        yield Observation()
        return
    manager = None
    observed = Observation(telemetry=telemetry)
    try:
        manager = telemetry.client.start_as_current_observation(
            name=name, as_type=as_type, **telemetry.clean(values)
        )
        observed.span = manager.__enter__()
    except Exception:
        _LOG.warning("Langfuse: наблюдение не создано")
        manager = None
    try:
        yield observed
    except BaseException as error:
        message = str(error) if isinstance(error, ModelCallError) else type(error).__name__
        observed.update(level="ERROR", status_message=message)
        raise
    finally:
        if manager is not None:
            try:
                # Исключения модели уже очищены; SDK не записывает чужую цепочку traceback.
                manager.__exit__(None, None, None)
            except Exception:
                _LOG.warning("Langfuse: наблюдение не завершено")


@contextmanager
def graph_execution(run_dir: Path | None, command: str) -> Iterator[dict[str, Any]]:
    telemetry = _CURRENT.get()
    if telemetry is None:
        yield {}
        return
    session = sha256(str((run_dir or Path.cwd()).resolve()).encode()).hexdigest()
    with propagate_attributes(session_id=session, trace_name=f"carousel {command}"):
        with observation(f"carousel {command}", as_type="span", metadata={"run": str(run_dir)}):
            try:
                callback = CallbackHandler(public_key=telemetry.public_key)
            except Exception:
                _LOG.warning("Langfuse: обработчик графа не создан")
                yield {}
            else:
                yield {"callbacks": [callback], "metadata": {"run": str(run_dir)}}


