async def _chat_stream(
    self, model: str, response: httpx2.Response, envelope: dict[str, Any]
) -> bool:
    """SSE и текст собирает SDK; исходные события сохраняются до нормализации."""
    state: ChatCompletionStreamState[Any] = ChatCompletionStreamState()
    events: list[Any] = []
    envelope["events"] = events
    done = False

    def invalid() -> None:
        usage = _usage(envelope.get("usage"))
        update_generation(output=envelope, usage_details=_usage_details(usage))
        raise self._failure(
            model, "bad_envelope", "ответ шлюза не похож на ответ чата",
            usage=usage, answered_model=_echoed_model(envelope),
        )

    async def body() -> AsyncIterator[bytes]:
        async for chunk in response.aiter_bytes():
            yield chunk
        # Шлюз может закрыть последнюю строку без пустой строки события.
        yield b"\n\n"

    async for event in SSEDecoder().aiter_bytes(body()):
        if not event.data:
            continue
        if event.data.strip() == "[DONE]":
            done = True
            break
        try:
            data = event.json()
        except ValueError:
            events.append(event.data)
            invalid()
        events.append(data)
        if not isinstance(data, dict):
            invalid()
        envelope.update(
            {key: value for key, value in data.items()
             if key not in ("choices", "usage", "model", "events")}
        )
        if isinstance(data.get("usage"), dict):
            envelope["usage"] = data["usage"]
        if not envelope.get("model") and data.get("model"):
            envelope["model"] = data["model"]
        if data.get("error"):
            return True
        choices = data.get("choices")
        if not isinstance(choices, list):
            continue
        normalized = []
        for choice in choices:
            if not isinstance(choice, dict):
                invalid()
            delta = choice.get("delta") or {}
            if not isinstance(delta, dict):
                invalid()
            # SDK склеивает любые строки и требует index у списков. Метаданные
            # провайдера оставляем в events, в накопитель идут только дельты ответа.
            delta = {key: value for key, value in delta.items()
                     if key in ("content", "reasoning", "refusal", "tool_calls")}
            normalized.append({**choice, "index": choice.get("index", 0), "delta": delta})
            if choice.get("native_finish_reason"):
                envelope["native_finish_reason"] = choice["native_finish_reason"]
        chunk = ChatCompletionChunk.construct(**{**data, "choices": normalized})
        try:
            state.handle_chunk(chunk)
        except (AttributeError, IndexError, TypeError, ValueError, RuntimeError):
            invalid()
        snapshot = state.current_completion_snapshot
        if snapshot.choices:
            envelope["choices"] = [choice.to_dict() for choice in snapshot.choices]
    choices = envelope.get("choices") or []
    if choices and envelope.get("native_finish_reason"):
        choices[0]["native_finish_reason"] = envelope["native_finish_reason"]
    return done or bool(choices and choices[0].get("finish_reason"))

