def media_identity(value: Any) -> Any:
    """SDK заменяет data URI ссылкой: сравниваем тип и хеш тех же байтов."""
    from langfuse.media import LangfuseMedia

    if isinstance(value, str) and value.startswith("data:"):
        header, encoded = value.split(",", 1)
        digest = base64.urlsafe_b64encode(sha256(base64.b64decode(encoded)).digest()).decode()[:22]
        return {"type": header[5:].split(";", 1)[0], "media_id": digest}
    if isinstance(value, str) and value.startswith("@@@langfuseMedia:"):
        parsed = LangfuseMedia.parse_reference_string(value)
        return {"type": parsed["content_type"], "media_id": parsed["media_id"]}
    if isinstance(value, list):
        return [media_identity(item) for item in value]
    if isinstance(value, dict):
        return {key: media_identity(item) for key, item in value.items()}
    return value


