class _HiddenLogs(logging.Filter):
    def __init__(self, telemetry: Telemetry) -> None:
        super().__init__()
        self._telemetry = telemetry

    def filter(self, record: logging.LogRecord) -> bool:
        record.msg = self._telemetry.redact(record.getMessage())
        record.args = ()
        if record.exc_info:
            record.exc_text = logging.Formatter().formatException(record.exc_info)
            record.exc_info = None
        if record.exc_text:
            record.exc_text = self._telemetry.redact(record.exc_text)
        if record.stack_info:
            record.stack_info = self._telemetry.redact(record.stack_info)
        return True


