    guard = _HiddenLogs(telemetry)
    prefixes = ("langfuse", "opentelemetry", "openai", "httpx", "httpx2")
    loggers = [logging.getLogger(name) for name in tuple(logging.Logger.manager.loggerDict)
               if name.split(".", 1)[0] in prefixes]
    handlers = {handler for logger in [logging.getLogger(), *loggers] for handler in logger.handlers}
    targets = [*loggers, *handlers]
    for target in targets:
        target.addFilter(guard)
    try:
        yield
    finally:
        for target in targets:
            target.removeFilter(guard)


