    items: list[dict] = []
    for path in sorted((ROOT / "carousel").rglob("*.py")):
        rel = path.relative_to(ROOT).as_posix()
        tree = ast.parse(path.read_text(encoding="utf-8"))
        for index, (kind, _, line) in enumerate(candidates(tree)):
            tests = executed.get((rel, line))
            if tests:
                items.append({"file": rel, "index": index, "kind": kind, "line": line, "tests": sorted(tests)})
    return items


def remove_tree(path: pathlib.Path) -> bool:
    """Удаление с ретраями: Windows держит handle. Сбой после ретраев — infrastructure, не вердикт."""

    def clear_readonly(func, target, _info):
        os.chmod(target, stat.S_IWRITE)
        func(target)

    for _ in range(20):
        try:
            shutil.rmtree(path, onerror=clear_readonly)
            return True
        except FileNotFoundError:
            return True
        except OSError:
            time.sleep(0.25)
    return not path.exists()


def make_worker(index: int) -> pathlib.Path:
    dst = WORK / f"w{index}"
    if dst.exists():
        remove_tree(dst)
    shutil.copytree(ROOT, dst, ignore=IGNORE)
    proc = subprocess.run(
        [str(PYTHON), "-c", "import carousel; print(carousel.__file__)"],
        cwd=dst, capture_output=True, text=True, encoding="utf-8", creationflags=NO_WINDOW, check=True,
    )
    imported = pathlib.Path(proc.stdout.strip()).resolve()
    if not imported.is_relative_to(dst.resolve()):
        raise RuntimeError(f"копия {dst} импортирует carousel из {imported}, а не из себя")
    return dst


def run_tests(worker: pathlib.Path, nodeids: list[str]) -> tuple[int, list[str]]:
    cmd = [
        str(PYTHON), "-m", "pytest", "-q", "-p", "no:cacheprovider", "-o", "addopts=",
        "-rf", "--tb=line", "--no-header", *nodeids,
    ]
    proc = subprocess.run(
        cmd, cwd=worker, capture_output=True, text=True, encoding="utf-8", errors="replace",
        timeout=RUN_TIMEOUT, creationflags=NO_WINDOW,
    )
    failed = [
        line[len("FAILED "):].split(" - ")[0]
        for line in proc.stdout.splitlines()
        if line.startswith("FAILED ")
    ]
    return proc.returncode, failed


class WorkerDirty(RuntimeError):
    pass


def run_mutant(worker: pathlib.Path, item: dict, pristine: bytes) -> dict:
    target = worker / item["file"]
    code, snippet = mutated_source(pristine.decode("utf-8"), item["index"])
    base = {k: item[k] for k in ("file", "index", "kind", "line")}
    base.update(snippet=snippet, tests=item["tests"])
    try:
        compile(code, item["file"], "exec")
    except SyntaxError:
        return {**base, "status": "invalid", "kills": []}
    started = time.time()
    try:
        target.write_bytes(code.encode("utf-8"))
        rc, failed = run_tests(worker, item["tests"])
    except subprocess.TimeoutExpired:
        rc, failed = -1, []
    finally:
        target.write_bytes(pristine)
    if sha(target.read_bytes()) != sha(pristine):
        raise WorkerDirty(item["file"])
    if rc == 0:
        status, kills = "survived", []
    elif rc == 1 and failed:
        rc2, failed_pristine = run_tests(worker, failed)
        if rc2 not in (0, 1):
            return {**base, "status": "infra", "kills": [], "seconds": round(time.time() - started, 1)}
        kills = [name for name in failed if name not in failed_pristine]
        status = "killed" if kills else "flaky"
        return {**base, "status": status, "kills": kills, "failed_on_mutant": failed,
                "seconds": round(time.time() - started, 1)}
    else:
        return {**base, "status": "infra", "kills": [], "seconds": round(time.time() - started, 1)}
    return {**base, "status": status, "kills": kills, "seconds": round(time.time() - started, 1)}


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    results_path = OUT / "results.jsonl"
    if os.environ.get("MUT_FRESH") == "1" and results_path.exists():
        results_path.unlink()
    done: set[tuple[str, int, int]] = set()
    if results_path.exists():
        for line in results_path.read_text(encoding="utf-8").splitlines():
            rec = json.loads(line)
            done.add((rec["file"], rec["index"], rec["line"]))

    executed = load_coverage()
    pool = eligible(executed)
    print(f"исполняемых мутируемых узлов: {len(pool)}")
    chosen = random.Random(SEED).sample(pool, min(SAMPLE, len(pool)))
    chosen = [item for item in chosen if (item["file"], item["index"], item["line"]) not in done]
    print(f"к прогону: {len(chosen)} (уже готово: {len(done)})")

    pristine = {item["file"]: (ROOT / item["file"]).read_bytes() for item in chosen}
    tasks: queue.Queue = queue.Queue()
    for item in chosen:
        tasks.put(item)
    lock = threading.Lock()
    counts: collections.Counter = collections.Counter()

    def loop(index: int) -> None:
        worker = make_worker(index)
        try:
            while True:
                try:
                    item = tasks.get_nowait()
                except queue.Empty:
                    return
                try:
                    rec = run_mutant(worker, item, pristine[item["file"]])
                except WorkerDirty:
                    rec = {**{k: item[k] for k in ("file", "index", "kind", "line")},
                           "status": "infra", "kills": [], "tests": item["tests"], "snippet": "dirty worker"}
                    remove_tree(worker)
                    worker = make_worker(index)
                with lock:
                    with results_path.open("a", encoding="utf-8") as fh:
                        fh.write(json.dumps(rec, ensure_ascii=False) + "\n")
                    counts[rec["status"]] += 1
                    print(f"[{sum(counts.values())}] {rec['status']:9} {rec['file']}:{rec['line']} {rec.get('snippet', '')[:60]!r}", flush=True)
        finally:
            if not remove_tree(worker):
                print(f"infrastructure: не удалилась копия {worker}", flush=True)

    threads = [threading.Thread(target=loop, args=(i,)) for i in range(WORKERS)]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()
    print("статусы:", dict(counts))


if __name__ == "__main__":
    main()

"""Мутационный гейт по тестам carousel/.

Мутант — одна правка одного узла AST: знак сравнения, `and`/`or` или целая константа. Мутант пишется
только в копию проекта (WORK), рабочее дерево не меняется. Тесты для мутанта — те, что исполняют его строку
по покрытию с контекстами (runs/_observability/cov_per_test_20261022.dat).

Мутант убит, если тест падает с AssertionError на мутанте и проходит на исходном коде. Другие падения
(TypeError, таймаут, ошибка сбора, пустой набор тестов) — не убийство: `crashed` или `infra`.

Без моделей и сети. Каждый результат пишется в results.jsonl сразу, упавший прогон не теряет работу.
baseline.json — прогон покрывающих тестов на исходнике. summary.json и summary.md — итог.
Переменные: MUT_SAMPLE (по умолчанию 400), MUT_FRESH=1 (стереть results.jsonl).
"""

from __future__ import annotations

