DATA = ROOT / "runs/_observability/cov_per_test_20261022.dat"
SAMPLE = int(os.environ.get("MUT_SAMPLE", "400"))
WORKERS = 4
SEED = 20261022
RUN_TIMEOUT = 240
NO_WINDOW = 0x08000000
ENV = {**os.environ, "PYTHONDONTWRITEBYTECODE": "1", "PYTHONIOENCODING": "utf-8"}
# Тесты с плавающими пикселями (Chromium): их падение не сигнал о мутанте, в гейт не берём.
EXCLUDE_FILES = {"tests/test_huatu_adapter.py"}
IGNORE = shutil.ignore_patterns(
    ".venv", ".venv-bdd", "runs", ".git", "site", "memory", "__pycache__", ".pytest_cache",
    "*.dat", "*.sqlite", ".coverage*", "node_modules", "htmlcov", "*.pyc",
)
CMP_FLIP = {
    ast.Lt: ast.LtE, ast.LtE: ast.Lt, ast.Gt: ast.GtE, ast.GtE: ast.Gt,
    ast.Eq: ast.NotEq, ast.NotEq: ast.Eq,
}
# Плагин pytest: оставляет в сборе только узлы из файла MUT_NODES, остальное не запускает.
# Список узлов идёт файлом, а не аргументами: длинная командная строка на Windows не влезает.
PLUGIN = (
    "import os\n"
    "import pathlib\n"
    "\n"
    "\n"
    "def pytest_collection_modifyitems(config, items):\n"
    "    wanted = set(pathlib.Path(os.environ['MUT_NODES']).read_text(encoding='utf-8').splitlines())\n"
    "    items[:] = [item for item in items if item.nodeid in wanted]\n"
)


class WorkerDirty(RuntimeError):
    """Файл копии после прогона не совпал с исходным: копию изымаем и пересобираем."""


def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def candidates(tree: ast.AST) -> list[tuple[str, ast.AST, int]]:
    """Все мутируемые узлы в фиксированном порядке. Строка — ближайший оператор-предок:
    покрытие считает строки операторов, а не выражений внутри них."""
    found: list[tuple[str, ast.AST, int]] = []

    def visit(node: ast.AST, stmt_line: int) -> None:
        for child in ast.iter_child_nodes(node):
            line = child.lineno if isinstance(child, ast.stmt) else stmt_line
            if isinstance(child, ast.Compare) and len(child.ops) == 1 and type(child.ops[0]) in CMP_FLIP:
                found.append(("cmp", child, line))
            elif isinstance(child, ast.BoolOp):
                found.append(("bool", child, line))
            elif isinstance(child, ast.Constant) and type(child.value) is int:
                found.append(("int", child, line))
            visit(child, line)

    visit(tree, 0)
    return found


def mutate(node: ast.AST, kind: str) -> None:
    if kind == "cmp":
        node.ops = [CMP_FLIP[type(node.ops[0])]()]  # type: ignore[attr-defined]
    elif kind == "bool":
        node.op = ast.Or() if isinstance(node.op, ast.And) else ast.And()  # type: ignore[attr-defined]
    else:
        node.value = node.value + 1  # type: ignore[attr-defined]


def mutated_source(src: str, index: int) -> tuple[str, str]:
    tree = ast.parse(src)
    kind, node, _ = candidates(tree)[index]
    snippet = ast.unparse(node)[:100]
    mutate(node, kind)
    return ast.unparse(tree), snippet


def load_coverage() -> dict[tuple[str, int], set[str]]:
    """(файл carousel, строка оператора) → узлы тестов, которые её исполняют."""
    cov = coverage.Coverage(data_file=str(DATA))
    cov.load()
    data = cov.get_data()
    executed: dict[tuple[str, int], set[str]] = collections.defaultdict(set)
    for measured in data.measured_files():
        try:
            rel = pathlib.Path(measured).resolve().relative_to(ROOT).as_posix()
        except ValueError:
            continue
        if not rel.startswith("carousel/"):
            continue
        for line, contexts in data.contexts_by_lineno(measured).items():
            for ctx in contexts:
                node = ctx.split("|")[0]
                if "::" in node and node.split("::", 1)[0] not in EXCLUDE_FILES:
                    executed[(rel, line)].add(node)
    return executed


def eligible(executed: dict[tuple[str, int], set[str]]) -> list[dict]:
    items: list[dict] = []
    for path in sorted((ROOT / "carousel").rglob("*.py")):
        rel = path.relative_to(ROOT).as_posix()
        tree = ast.parse(path.read_text(encoding="utf-8"))
        for index, (kind, _, line) in enumerate(candidates(tree)):
            tests = executed.get((rel, line))
            if tests:
                items.append({"file": rel, "index": index, "kind": kind, "line": line, "tests": sorted(tests)})
    return items


def base_of(item: dict) -> dict:
    return {k: item[k] for k in ("file", "index", "kind", "line", "tests")}


def remove_tree(path: pathlib.Path) -> bool:
    """Удаление с ретраями: Windows держит handle. Сбой после ретраев — infrastructure, не вердикт."""

    def clear_readonly(func, target, _info):
        os.chmod(target, stat.S_IWRITE)
        func(target)

    for _ in range(20):
        try:
            shutil.rmtree(path, onerror=clear_readonly)
            return True
        except FileNotFoundError:
            return True
        except OSError:
            time.sleep(0.25)
    return not path.exists()


def write_retry(path: pathlib.Path, data: bytes) -> None:
    for _ in range(20):
        try:
            path.write_bytes(data)
            return
        except PermissionError:
            time.sleep(0.25)
    path.write_bytes(data)


def make_worker(tag: str) -> pathlib.Path:
    dst = WORK / f"{tag}-{uuid.uuid4().hex[:8]}"
    shutil.copytree(ROOT, dst, ignore=IGNORE)
    (dst / "mutsel.py").write_text(PLUGIN, encoding="utf-8")
    proc = subprocess.run(
        [str(PYTHON), "-c", "import carousel; print(carousel.__file__)"],
        cwd=dst, capture_output=True, text=True, encoding="utf-8", env=ENV,
        creationflags=NO_WINDOW, check=True,
    )
    imported = pathlib.Path(proc.stdout.strip()).resolve()
    if not imported.is_relative_to(dst.resolve()):
        raise RuntimeError(f"копия {dst} импортирует carousel из {imported}, а не из себя")
    return dst


def run_tests(worker: pathlib.Path, nodeids: list[str]) -> tuple[int, dict[str, str]]:
    """Прогон выбранных узлов. Возвращает (код выхода, {узел: причина падения}). Таймаут — код -1."""
    nodes_file = worker / "mut_nodes.txt"
    nodes_file.write_text("\n".join(nodeids), encoding="utf-8")
    files = sorted({node.split("::", 1)[0] for node in nodeids})
    env = {**ENV, "MUT_NODES": str(nodes_file)}
    cmd = [
        str(PYTHON), "-m", "pytest", "-q", "-p", "no:cacheprovider", "-p", "mutsel",
        "-o", "addopts=", "-rf", "--tb=line", "--no-header", *files,
    ]
    try:
        proc = subprocess.run(
            cmd, cwd=worker, capture_output=True, text=True, encoding="utf-8", errors="replace",
            env=env, timeout=RUN_TIMEOUT, creationflags=NO_WINDOW,
        )
    except subprocess.TimeoutExpired:
        return -1, {}
    failed: dict[str, str] = {}
    for line in proc.stdout.splitlines():
        if line.startswith("FAILED "):
            name, _, reason = line[len("FAILED "):].partition(" - ")
            failed[name] = reason
    return proc.returncode, failed


def is_assert(reason: str) -> bool:
    """Падение — проверка ожидания: `assert …` в короткой сводке pytest или AssertionError."""
    head = reason.lstrip()
    return head.startswith("assert") or "AssertionError" in reason or "DID NOT RAISE" in reason


def run_mutant(worker: pathlib.Path, item: dict, pristine: bytes) -> dict:
    target = worker / item["file"]
    code, snippet = mutated_source(pristine.decode("utf-8"), item["index"])
    rec = {**base_of(item), "snippet": snippet}
    try:
        compile(code, item["file"], "exec")
    except SyntaxError:
        return {**rec, "status": "invalid", "kills": []}
    started = time.time()
    try:
        write_retry(target, code.encode("utf-8"))
        rc, failed = run_tests(worker, item["tests"])
    finally:
        write_retry(target, pristine)
    if sha(target.read_bytes()) != sha(pristine):
        raise WorkerDirty(item["file"])
    rec["seconds"] = round(time.time() - started, 1)
    if rc == 0:
        return {**rec, "status": "survived", "kills": []}
    if rc != 1 or not failed:
        return {**rec, "status": "infra", "kills": [], "reason": f"код {rc}"}
    # Упавшие тесты перепроверяем на исходнике: то, что падает и там, не доказывает мутанта.
    rc2, failed_pristine = run_tests(worker, sorted(failed))
    if rc2 not in (0, 1):
        return {**rec, "status": "infra", "kills": [], "reason": f"исходник: код {rc2}"}
    kills = sorted(name for name, reason in failed.items() if is_assert(reason) and name not in failed_pristine)
    if kills:
        return {**rec, "status": "killed", "kills": kills, "failed_on_mutant": failed}
    if all(name in failed_pristine for name in failed):
        return {**rec, "status": "flaky", "kills": [], "failed_on_mutant": failed}
    return {**rec, "status": "crashed", "kills": [], "failed_on_mutant": failed}


def baseline(nodeids: list[str]) -> dict:
    worker = make_worker("base")
    try:
        rc, failed = run_tests(worker, nodeids)
    finally:
        if not remove_tree(worker):
            print(f"infrastructure: не удалилась копия {worker}", flush=True)
    return {"rc": rc, "tests": len(nodeids), "failed": failed}


def summarize(results_path: pathlib.Path) -> None:
    records = [json.loads(line) for line in results_path.read_text(encoding="utf-8").splitlines() if line.strip()]
    statuses = collections.Counter(rec["status"] for rec in records)
    covered: collections.Counter = collections.Counter()
    killed_by: collections.Counter = collections.Counter()
    for rec in records:
        if rec["status"] in ("invalid", "infra"):
            continue
        covered.update(rec["tests"])
        killed_by.update(rec.get("kills", []))
    rows = [{"test": name, "covered": covered[name], "kills": killed_by[name]} for name in sorted(covered)]
    zero = sorted((row for row in rows if row["kills"] == 0), key=lambda row: -row["covered"])
    survived = [
        {"file": rec["file"], "line": rec["line"], "kind": rec["kind"], "snippet": rec.get("snippet", "")}
        for rec in records if rec["status"] == "survived"
    ]
    summary = {
        "mutants": len(records),
        "statuses": dict(statuses),
        "tests_covering": len(rows),
        "tests_with_kill": len(rows) - len(zero),
        "tests_zero_kill": len(zero),
        "survived": survived,
        "rows": rows,
    }
    (OUT / "summary.json").write_text(json.dumps(summary, ensure_ascii=False, indent=1), encoding="utf-8")
    lines = [
        "# Мутационный гейт: итог",
        "",
        f"Мутантов с результатом: {len(records)}. Статусы: {dict(statuses)}.",
        f"Тестов, исполнивших хотя бы один мутант: {len(rows)}. Убили хотя бы один: {len(rows) - len(zero)}. "
        f"Не убили ни одного: {len(zero)}.",
        "",
        "## Выжившие мутанты",
        "",
    ]
    lines += [f"- `{s['file']}:{s['line']}` {s['kind']} `{s['snippet']}`" for s in survived[:60]]
    lines += ["", "## Тесты без убийств (по числу исполненных мутантов)", ""]
    lines += [f"- `{row['test']}` — исполнил {row['covered']}" for row in zero[:80]]
    (OUT / "summary.md").write_text("\n".join(lines) + "\n", encoding="utf-8")


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    results_path = OUT / "results.jsonl"
    if os.environ.get("MUT_FRESH") == "1" and results_path.exists():
        results_path.unlink()
    done: set[tuple[str, int, int]] = set()
    if results_path.exists():
        for line in results_path.read_text(encoding="utf-8").splitlines():
            if line.strip():
                rec = json.loads(line)
                done.add((rec["file"], rec["index"], rec["line"]))

    executed = load_coverage()
    pool = eligible(executed)
    print(f"исполняемых мутируемых узлов: {len(pool)}", flush=True)
    chosen = random.Random(SEED).sample(pool, min(SAMPLE, len(pool)))
    todo = [item for item in chosen if (item["file"], item["index"], item["line"]) not in done]
    print(f"к прогону: {len(todo)} (уже готово: {len(done)})", flush=True)
    if not todo:
        summarize(results_path)
        return

    covering = sorted({node for item in todo for node in item["tests"]})
    base = baseline(covering)
    (OUT / "baseline.json").write_text(json.dumps(base, ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"исходник: код {base['rc']}, тестов {base['tests']}, упало {len(base['failed'])}", flush=True)

    pristine = {item["file"]: (ROOT / item["file"]).read_bytes() for item in todo}
    tasks: queue.Queue = queue.Queue()
    for item in todo:
        tasks.put(item)
    lock = threading.Lock()
    counts: collections.Counter = collections.Counter()

    def record(rec: dict) -> None:
        with lock:
            with results_path.open("a", encoding="utf-8") as fh:
                fh.write(json.dumps(rec, ensure_ascii=False) + "\n")
            counts[rec["status"]] += 1
            print(f"[{sum(counts.values())}/{len(todo)}] {rec['status']:9} "
                  f"{rec['file']}:{rec['line']} {rec.get('snippet', '')[:60]!r}", flush=True)

    def loop(index: int) -> None:
        worker = make_worker(f"w{index}")
        try:
            while True:
                try:
                    item = tasks.get_nowait()
                except queue.Empty:
                    return
                try:
                    rec = run_mutant(worker, item, pristine[item["file"]])
                except WorkerDirty:
                    rec = {**base_of(item), "status": "infra", "kills": [], "reason": "копия загрязнена"}
                    remove_tree(worker)
                    worker = make_worker(f"w{index}")
                except Exception as error:  # один мутант не роняет гейт
                    rec = {**base_of(item), "status": "infra", "kills": [], "reason": repr(error)[:200]}
                record(rec)
        finally:
            if not remove_tree(worker):
                print(f"infrastructure: не удалилась копия {worker}", flush=True)

    threads = [threading.Thread(target=loop, args=(i,)) for i in range(WORKERS)]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()
    summarize(results_path)
    print("статусы этого прогона:", dict(counts), flush=True)


if __name__ == "__main__":
    main()

"""Пачки для полного прогона скила test-junk-audit: тело теста с декораторами и начало вызываемого кода.

Факты: исходный текст и определения. Вердикт не выносится. Вход — groups/group{1..6}.tsv.
Пишет chunks/chunk_NN.md по CHUNK функций и chunks/index.tsv (пачка → узлы).
"""

from __future__ import annotations

import ast
import pathlib

ROOT = pathlib.Path("E:/repos/carousel-demo")
BASE = ROOT / "runs/_observability/skills/test-junk-audit"
CHUNK = 40


def function_node(tree: ast.Module, name: str, line: int) -> ast.FunctionDef | ast.AsyncFunctionDef | None:
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == name:
            start = node.decorator_list[0].lineno if node.decorator_list else node.lineno
            if node.lineno == line or start <= line <= node.lineno:
                return node
    return None


def carousel_index() -> dict[str, list[tuple[str, int]]]:
    index: dict[str, list[tuple[str, int]]] = {}
    for path in sorted((ROOT / "carousel").rglob("*.py")):
        tree = ast.parse(path.read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                index.setdefault(node.name, []).append((path.relative_to(ROOT).as_posix(), node.lineno))
    return index


def snippet(file: str, line: int, lines: int = 14) -> str:
    text = (ROOT / file).read_text(encoding="utf-8").splitlines()
    return "\n".join(f"{n + 1:5} {text[n]}" for n in range(line - 1, min(len(text), line - 1 + lines)))


def block(row: dict, index: dict[str, list[tuple[str, int]]], cache: dict[str, str]) -> list[str]:
    file, name, line = row["file"], row["name"], int(row["line"])
    if file not in cache:
        cache[file] = (ROOT / file).read_text(encoding="utf-8")
    src = cache[file]
    tree = ast.parse(src)
    node = function_node(tree, name, line)
    out = [f"## {file}::{name}  (строка {line}, покрыто строк проекта: {row['carousel_lines']})"]
    if node is None:
        out += ["НЕ НАЙДЕНА В ФАЙЛЕ", ""]
        return out
    start = node.decorator_list[0].lineno if node.decorator_list else node.lineno
    body = "\n".join(src.splitlines()[start - 1 : node.end_lineno])
    out += ["```python", body, "```"]
    names = {n.id for n in ast.walk(node) if isinstance(n, ast.Name)}
    names |= {n.attr for n in ast.walk(node) if isinstance(n, ast.Attribute)}
    local = {n.name for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.ClassDef))}
    shown = 0
    for ident in sorted(names):
        if ident in local or ident not in index or shown >= 3:
            continue
        defs = index[ident]
        if len(defs) != 1:
            continue
        file_def, line_def = defs[0]
        out += [f"### производственный код: `{ident}` — {file_def}:{line_def}", "```python",
                snippet(file_def, line_def), "```"]
        shown += 1
    out.append("")
    return out


def main() -> None:
    rows: list[dict] = []
    for group in range(1, 7):
        lines = (BASE / "groups" / f"group{group}.tsv").read_text(encoding="utf-8").splitlines()[1:]
        for line in lines:
            nodeid, lineno, cases, carousel = line.split("\t")
            file, name = nodeid.split("::", 1)
            rows.append({"group": group, "file": file, "name": name, "line": lineno,
                         "cases": cases, "carousel_lines": carousel})
    index = carousel_index()
    cache: dict[str, str] = {}
    out_dir = BASE / "chunks"
    out_dir.mkdir(exist_ok=True)
    for old in out_dir.glob("chunk_*.md"):
        old.unlink()
    index_rows = ["chunk\tnodeid"]
    for number, start in enumerate(range(0, len(rows), CHUNK), 1):
        part = rows[start : start + CHUNK]
        lines = [f"# Пачка {number:02d}: {len(part)} функций", ""]
        for row in part:
            lines += block(row, index, cache)
            index_rows.append(f"{number:02d}\t{row['file']}::{row['name']}")
        (out_dir / f"chunk_{number:02d}.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    (out_dir / "index.tsv").write_text("\n".join(index_rows) + "\n", encoding="utf-8")
    print(f"функций: {len(rows)}, пачек: {(len(rows) + CHUNK - 1) // CHUNK}")


if __name__ == "__main__":
    main()

