"""Инструмент скила test-junk-audit: инвентарь тестов, облегчённые пачки для читателей, сводка вердиктов, удаление по AST.

  python junkaudit.py pack   --tests tests --out DIR [--parts 10] [--max-lines 60]
  python junkaudit.py report --out DIR --verdicts verdicts1,verdicts2 [--restore restore.txt] [--exclude a.py,b.py]
  python junkaudit.py apply  (те же ключи, что у report; удаляет JUNK)

Вердикт читателя, строка на функцию:  номер ;; KEEP|STAY|JUNK ;; категория ;; причина
Номер — сквозной номер из DIR/index.tsv. Строки с JUNK из любого прохода сильнее KEEP.
"""

from __future__ import annotations

import argparse
import ast
import collections
import math
import pathlib
import re

LINE = re.compile(r"^\s*(\d+)\s*;;\s*(KEEP|STAY|JUNK)\s*;;\s*([^;]*?)\s*;;\s*(.*)$", re.IGNORECASE)


def span(node: ast.FunctionDef | ast.AsyncFunctionDef) -> tuple[int, int]:
    start = node.decorator_list[0].lineno if node.decorator_list else node.lineno
    return start, node.end_lineno or node.lineno


def cases_of(node: ast.FunctionDef | ast.AsyncFunctionDef) -> int:
    total = 1
    for deco in node.decorator_list:
        call = deco if isinstance(deco, ast.Call) else None
        if call and ast.unparse(call.func).endswith("parametrize") and len(call.args) >= 2:
            values = call.args[1]
            if isinstance(values, (ast.List, ast.Tuple)):
                total *= max(1, len(values.elts))
    return total


def inventory(tests: pathlib.Path) -> list[tuple[str, str, int, int]]:
    rows: list[tuple[str, str, int, int]] = []
    for path in sorted(tests.rglob("test_*.py")):
        tree = ast.parse(path.read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name.startswith("test"):
                rows.append((path.as_posix(), node.name, span(node)[0], cases_of(node)))
    rows.sort(key=lambda r: (r[0], r[2]))
    return rows


def pack(args: argparse.Namespace) -> None:
    rows = inventory(pathlib.Path(args.tests))
    out = pathlib.Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    (out / "index.tsv").write_text(
        "n\tfile\tname\tline\tcases\n" + "\n".join(f"{i}\t{f}\t{n}\t{ln}\t{c}" for i, (f, n, ln, c) in enumerate(rows, 1)) + "\n",
        encoding="utf-8",
    )
    size = math.ceil(len(rows) / args.parts)
    sources: dict[str, list[str]] = {}
    for part in range(args.parts):
        chunk = rows[part * size : (part + 1) * size]
        if not chunk:
            continue
        text = [f"# Пачка {part + 1:02d}", ""]
        for offset, (file, name, line, cases) in enumerate(chunk):
            lines = sources.setdefault(file, pathlib.Path(file).read_text(encoding="utf-8").splitlines())
            tree = ast.parse("\n".join(lines))
            body = "НЕ НАЙДЕНА"
            for node in ast.walk(tree):
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == name and span(node)[0] == line:
                    start, end = span(node)
                    chosen = lines[start - 1 : end]
                    if len(chosen) > args.max_lines:
                        chosen = chosen[: args.max_lines] + [f"    # … ещё {len(chosen) - args.max_lines} строк"]
                    body = "\n".join(chosen)
                    break
            note = f", кейсов {cases}" if cases > 1 else ""
            text += [f"## {part * size + offset + 1} {file}{note}", "```python", body, "```", ""]
        (out / f"pack_{part + 1:02d}.md").write_text("\n".join(text) + "\n", encoding="utf-8")
    print(f"функций {len(rows)}, кейсов {sum(r[3] for r in rows)}, пачек {args.parts} по {size}")


def read_verdicts(folder: pathlib.Path) -> tuple[dict[int, tuple[str, str, str]], list[str]]:
    found: dict[int, tuple[str, str, str]] = {}
    bad: list[str] = []
    for path in sorted(folder.glob("*.txt")):
        for raw in path.read_text(encoding="utf-8").splitlines():
            if not raw.strip():
                continue
            match = LINE.match(raw)
            if not match:
                bad.append(f"{path.name}: {raw[:90]}")
                continue
            kind = "KEEP" if match.group(2).upper() == "STAY" else match.group(2).upper()
            found[int(match.group(1))] = (kind, match.group(3).strip().upper(), match.group(4).strip())
    return found, bad


def merge(out: pathlib.Path, folders: list[str], restore: str | None) -> tuple[dict[int, tuple[str, str, str]], list[str]]:
    merged: dict[int, tuple[str, str, str]] = {}
    problems: list[str] = []
    for folder in folders:
        found, bad = read_verdicts(out / folder)
        problems += bad
        for number, verdict in found.items():
            if number not in merged or (verdict[0] == "JUNK" and merged[number][0] == "KEEP"):
                merged[number] = verdict
    if restore and pathlib.Path(restore).exists():
        for number in map(int, pathlib.Path(restore).read_text(encoding="utf-8").split()):
            merged[number] = ("KEEP", "ВОЗВРАТ", "возвращён после чтения")
    return merged, problems


def delete(file: pathlib.Path, targets: list[tuple[str, int]]) -> int:
    source = file.read_text(encoding="utf-8")
    lines = source.splitlines(keepends=True)
    spans: list[tuple[int, int]] = []
    tree = ast.parse(source)
    for name, line in targets:
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == name and span(node)[0] == line:
                spans.append(span(node))
                break
        else:
            raise SystemExit(f"не найдена {file}::{name} на строке {line}: пересоберите пачки после правки файла")
    for start, end in sorted(spans, reverse=True):
        del lines[start - 1 : end]
    new = "".join(lines)
    ast.parse(new)
    tmp = file.with_suffix(".tmp")
    tmp.write_text(new, encoding="utf-8", newline="")
    tmp.replace(file)
    return len(spans)


def report(args: argparse.Namespace, apply: bool) -> None:
    out = pathlib.Path(args.out)
    index = [line.split("\t") for line in (out / "index.tsv").read_text(encoding="utf-8").splitlines()[1:]]
    funcs = [(f, n, int(ln), int(c)) for _, f, n, ln, c in index]
    verdicts, bad = merge(out, args.verdicts.split(","), args.restore)
    missing = [n for n in range(1, len(funcs) + 1) if n not in verdicts]
    junk = [n for n, v in verdicts.items() if v[0] == "JUNK"]
    keep = [n for n, v in verdicts.items() if v[0] == "KEEP"]
    excluded = {e.strip() for e in args.exclude.split(",") if e.strip()}
    doomed = [n for n in junk if pathlib.PurePath(funcs[n - 1][0]).name not in {pathlib.PurePath(e).name for e in excluded}]
    cases = lambda ns: sum(funcs[n - 1][3] for n in ns)  # noqa: E731
    print(f"функций {len(funcs)}, без вердикта {len(missing)}, нечитаемых строк {len(bad)}")
    print(f"KEEP {len(keep)} ({cases(keep)} кейсов), JUNK {len(junk)} ({cases(junk)} кейсов), к удалению {len(doomed)} ({cases(doomed)} кейсов)")
    print("JUNK по видам:", dict(collections.Counter(verdicts[n][1] for n in junk).most_common()))
    if not apply:
        return
    if missing or bad:
        raise SystemExit("есть пропуски или нечитаемые строки: удаление не запущено")
    per_file: dict[str, list[tuple[str, int]]] = collections.defaultdict(list)
    for n in doomed:
        per_file[funcs[n - 1][0]].append((funcs[n - 1][1], funcs[n - 1][2]))
    print("удалено функций:", sum(delete(pathlib.Path(f), t) for f, t in per_file.items()))


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("command", choices=["pack", "report", "apply"])
    parser.add_argument("--tests", default="tests")
    parser.add_argument("--out", required=True)
    parser.add_argument("--parts", type=int, default=10)
    parser.add_argument("--max-lines", type=int, default=60)
    parser.add_argument("--verdicts", default="verdicts1")
    parser.add_argument("--restore")
    parser.add_argument("--exclude", default="")
    args = parser.parse_args()
    if args.command == "pack":
        pack(args)
    else:
        report(args, apply=args.command == "apply")


if __name__ == "__main__":
    main()

