from __future__ import annotations

from typing import Literal, Self

from pydantic import model_validator

from carousel.schemas import Contract, Text

AnalyzeProcess = Literal["reflection", "choice"]


class ClaimAssessment(Contract):
    option: int
    accepted: bool
    reason: Text


class ClaimReview(Contract):
    assessments: list[ClaimAssessment]

    @classmethod
    def bound_to(cls, size: int) -> type[Self]:
        class Bound(cls):  # type: ignore[valid-type, misc]
            @model_validator(mode="after")
            def _every_option_once(self) -> Self:
                numbers = [item.option for item in self.assessments]
                if sorted(numbers) != list(range(size)):
                    raise ValueError("пригодность каждого варианта проверяется ровно раз")
                return self

        Bound.__name__ = Bound.__qualname__ = cls.__name__
        return Bound

    def accepted(self) -> list[int]:
        return [item.option for item in self.assessments if item.accepted]


class ClaimPreference(Contract):
    winner: Literal["A", "B", "tie"]
    reason: Text


class ClaimPair(Contract):
    first: int
    second: int
    forward: ClaimPreference
    reverse: ClaimPreference

    def winner(self) -> int | None:
        if self.forward.winner == "A" and self.reverse.winner == "B":
            return self.first
        if self.forward.winner == "B" and self.reverse.winner == "A":
            return self.second
        return None


class MainIdeaChoice(Contract):
    review: ClaimReview
    pairs: list[ClaimPair]
    selected: int | None
    reason: Text

    @classmethod
    def of(cls, review: ClaimReview, pairs: list[ClaimPair]) -> Self:
        accepted = review.accepted()
        wins = {number: 0 for number in accepted}
        for pair in pairs:
            winner = pair.winner()
            if winner is not None:
                wins[winner] += 1
        leaders = [n for n in accepted if wins[n] == max(wins.values())] if wins else []
        selected = leaders[0] if len(leaders) == 1 else None
        reason = (
            "Единственный пригодный вариант"
            if len(accepted) == 1
            else "Единственный лидер попарного сравнения в обоих порядках"
            if selected is not None
            else "Нет пригодных вариантов"
            if not accepted
            else "Нет единственного победителя: ничья или зависимость от порядка"
        )
        return cls(review=review, pairs=pairs, selected=selected, reason=reason)

