def prompt_texts(path: Path) -> list[tuple[int, str]]:
    """Текст задания с номером строки.

    У шага задание — строковый литерал модуля, поэтому читаются литералы, а не файл целиком: иначе
    находкой станет имя класса, поля или импорта. У скилла текст задания и есть файл.
    """
    if path.suffix != ".py":
        return list(enumerate(path.read_text(encoding="utf-8").splitlines(), start=1))
    tree = ast.parse(path.read_text(encoding="utf-8"))
    return [
        (node.lineno, node.value)
        for node in ast.walk(tree)
        if isinstance(node, ast.Constant) and isinstance(node.value, str)
    ]


