def call(path: str, key: str, body: dict | None = None, timeout: int = 30) -> tuple[int, dict]:
    data = json.dumps(body).encode() if body is not None else None
    request = urllib.request.Request(
        BASE + path, data=data, headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"}
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return response.status, json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as error:
        try:
            return error.code, json.loads(error.read().decode("utf-8"))
        except Exception:  # noqa: BLE001
            return error.code, {"raw": "<не JSON>"}
    except Exception as error:  # noqa: BLE001
        return 0, {"error": f"{type(error).__name__}: {error}"[:200]}


def main() -> None:
    key = load_key()

    status, payload = call("/models?output_modalities=decisions", key)
    models = payload.get("data", [])
    print(f"decision-моделей по фильтру: {len(models)}  (status {status})")
    for model in models:
        print(f"  {model['id']:<45} ctx={model.get('context_length')}")
    print()

    targets = [
        "typesafe/jev-1.14",
        "typesafe/jev-latest",
