    ]
    print("пробный chat-вызов каждому id:")
    for target in targets:
        body = {
            "model": target,
            "messages": [{"role": "user", "content": "Ответь одним словом: да"}],
            "max_tokens": 16,
        }
        status, payload = call("/chat/completions", key, body)
        if status == 200:
            msg = payload.get("choices", [{}])[0].get("message", {})
            print(f"  {target:<28} 200  text={str(msg.get('content'))[:60]!r} "
                  f"usage={payload.get('usage', {}).get('total_tokens')}")
        else:
            err = payload.get("error", payload)
            print(f"  {target:<28} {status}  {json.dumps(err, ensure_ascii=False)[:160]}")


if __name__ == "__main__":
