        if block.get("type") == "text":
            parts.append(block.get("text") or "")
        elif block.get("type") == "tool_use":
            parts.append(json.dumps(block.get("input") or {}, ensure_ascii=False))
    return "\n".join(part for part in parts if part).strip()


