    console.log(`\nвывод: скан стоит ${first.ms} мс холодный, ${second.ms} мс прогретый`);
    console.log(`        два скана в тестах подряд: ${total} мс`);
  } finally {
    await rm(outputDir, { recursive: true, force: true, maxRetries: 20, retryDelay: 250 });
  }
}

