/**
 * Замер MCP-режима jscpd: сколько стоит старт, скан и проверка фрагмента после него.
 *
 * Разница важна: если держать сервер живым, проверка фрагмента не должна
 * пересканировать репозиторий. Это и решает, годится ли `--mcp` для `Stop`-хука.
 *
 * Запуск: node --experimental-strip-types scripts/mcp-probe.ts <путь-репо> <файл-фрагмента>
 */

import { spawn, type ChildProcessWithoutNullStreams } from "node:child_process";
import { readFile } from "node:fs/promises";

interface Pending {
  resolve: (value: unknown) => void;
  reject: (error: Error) => void;
}

class McpClient {
  private child: ChildProcessWithoutNullStreams;
  private buffer = "";
  private nextId = 1;
  private pending = new Map<number, Pending>();

  constructor(path: string) {
    this.child = spawn("jscpd", ["--mcp", path], { shell: true, windowsHide: true });
    this.child.stdout.on("data", (chunk: Buffer) => this.onData(chunk.toString("utf8")));
    this.child.stderr.on("data", () => {
      /* jscpd пишет прогресс в stderr, он тут не нужен */
    });
  }

  private onData(text: string): void {
    this.buffer += text;
    let index = this.buffer.indexOf("\n");
    while (index !== -1) {
      const line = this.buffer.slice(0, index).trim();
      this.buffer = this.buffer.slice(index + 1);
      index = this.buffer.indexOf("\n");
      if (line === "") continue;
      let message: { id?: number; result?: unknown; error?: { message?: string } };
      try {
        message = JSON.parse(line);
      } catch {
        continue;
      }
      if (typeof message.id !== "number") continue;
      const waiter = this.pending.get(message.id);
      if (!waiter) continue;
      this.pending.delete(message.id);
      if (message.error) waiter.reject(new Error(message.error.message ?? "ошибка MCP"));
      else waiter.resolve(message.result);
    }
  }

  request(method: string, params: unknown): Promise<unknown> {
    const id = this.nextId++;
    const payload = JSON.stringify({ jsonrpc: "2.0", id, method, params });
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.child.stdin.write(`${payload}\n`);
    });
  }

  notify(method: string): void {
    this.child.stdin.write(`${JSON.stringify({ jsonrpc: "2.0", method })}\n`);
  }

  close(): void {
    this.child.stdin.end();
    this.child.kill();
  }
}

async function timed<T>(label: string, work: () => Promise<T>): Promise<T> {
  const started = performance.now();
  const value = await work();
  console.log(`  ${label}: ${Math.round(performance.now() - started)} мс`);
  return value;
}

async function main(): Promise<void> {
  const [path, snippetPath] = process.argv.slice(2);
  if (!path || !snippetPath) {
    console.error("нужно: scripts/mcp-probe.ts <путь-репо> <файл-фрагмента>");
    process.exit(2);
  }
  const code = await readFile(snippetPath, "utf8");

  console.log("1. Старт сервера и initialize:");
  const client = new McpClient(path);
  await timed("initialize", () =>
    client.request("initialize", {
      protocolVersion: "2024-11-05",
      capabilities: {},
      clientInfo: { name: "anti-bike-probe", version: "1" },
    }),
  );
  client.notify("notifications/initialized");

  console.log("\n2. Список инструментов:");
  const tools = (await timed("tools/list", () => client.request("tools/list", {}))) as {
    tools: { name: string }[];
  };
  console.log(`     инструменты: ${tools.tools.map((tool) => tool.name).join(", ")}`);

  console.log("\n3. check_duplication на прогретом сервере (три раза подряд):");
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    const result = (await timed(`проверка ${attempt}`, () =>
      client.request("tools/call", {
        name: "check_duplication",
        arguments: { code, format: "python", kinds: ["exact", "renamed"] },
      }),
    )) as { content?: { text?: string }[] };
    const text = result.content?.[0]?.text ?? "";
    try {
      const parsed = JSON.parse(text) as { count?: number; duplications?: unknown[] };
      console.log(`     клонов: ${parsed.count}, отдано: ${parsed.duplications?.length ?? 0}`);
    } catch {
      console.log(`     не JSON: ${text.slice(0, 200)}`);
    }
  }

  console.log("\n4. check_current_directory после правки:");
  const rescanned = (await timed("пересканировать", () =>
    client.request("tools/call", { name: "check_current_directory", arguments: {} }),
  )) as { content?: { text?: string }[] };
  const text = rescanned.content?.[0]?.text ?? "";
  try {
    const parsed = JSON.parse(text) as { clones?: number; files?: number };
    console.log(`     файлов: ${parsed.files}, клонов: ${parsed.clones}`);
  } catch {
    console.log(`     не JSON: ${text.slice(0, 200)}`);
  }

  client.close();
}

await main();

/**
 * Ступень 1: обещает ли текст завести новую сущность. Без модели, без сети.
 *
 * Это отсев, а не решение. Его работа — не пустить к модели те ходы, где писать
 * нечего. Ложный пропуск тут дешевле ложного срабатывания: ход уйдёт в модель
 * и получит «нет».
 *
 * Почему глагол плюс существительное, а не слово «велосипед»: на замерах вопрос
 * «это велосипед?» дал обратный ответ, а поиск обещания сущности — верный.
 */

/** Глаголы, которыми агент объявляет, что сейчас что-то заведёт. */
const VERBS = [
  "введ",
  "добавл",
  "созда",
  "сдела",
  "предлаг",
  "завед",
  "напиш",
  "реализу",
  "вынес",
  "собер",
  "определ",
  "заведу",
  "постро",
];

/** Сущности, которые означают новый код в проекте. */
const NOUNS = [
  "класс",
  "объект",
  "датакласс",
  "dataclass",
  "слой",
  "прослойк",
  "обёртк",
  "обертк",
  "абстракци",
  "контейнер",
  "адаптер",
  "менеджер",
  "раннер",
  "сервис",
  "модуль",
  "функци",
  "хелпер",
  "хелпер",
  "утилит",
  "флаг",
  "ключ конфига",
  "переключател",
];

export interface Intent {
  /** Есть ли в тексте обещание завести новую сущность. */
  promise: boolean;
  /** Что именно нашлось: нужно для сообщения и для замеров. */
  matches: string[];
}

/**
 * Ищет в тексте обещание новой сущности.
 *
 * Условие — глагол и существительное в пределах одного предложения.
 * Пара через всё сообщение даёт ложные срабатывания: отчёт «я сделал X» и
 * отдельно «модуль Y уже есть» не обещают новую сущность.
 */
export function detectIntent(text: string): Intent {
  const matches: string[] = [];
  // Предложения режем по точке, восклицательному, вопросительному и переводу строки.
  for (const sentence of text.split(/(?<=[.!?])\s+|\n+/)) {
    const lower = sentence.toLowerCase();
    const verb = VERBS.find((candidate) => lower.includes(candidate));
    if (!verb) continue;
    const noun = NOUNS.find((candidate) => lower.includes(candidate));
    if (!noun) continue;
    matches.push(`${verb}…${noun}`);
  }
  return { promise: matches.length > 0, matches };
}

/**
 * Ступень 1: отсев по тексту (AB-01).
 *
 * Тексты взяты из настоящей сессии. Каждый тест называет, какую поломку ловит.
 */

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { detectIntent } from "../src/intent.ts";

// Настоящий велосипед: опция вопроса, предложившая свой RunContext.
const BIKE = "Один срез: RunContext — ввести объект «окружение шага» "
  + "(prices/budget_limit/limits/max_output_tokens/clock) и провести через 16 узлов.";

// Настоящий отчёт без обещания.
const REPORT = "Независимое ревью нашло, что выделенная запись историй не упростила код: "
  + "она только перенесла тот же цикл с шестью аргументами. Верну цикл на место.";

// Исправленный ход: тот же RunContext, но со ссылкой на готовое.
const FIXED = "Штатный механизм: StateGraph(state_schema, context_schema=Context), "
  + "Runtime[Context] в узле подставляется сам. Перейду на него, свой объект не ввожу.";

describe("detectIntent", () => {
  it("AB-01: находит обещание нового объекта в настоящем велосипеде", () => {
    const intent = detectIntent(BIKE);
    assert.equal(intent.promise, true, "велосипед не опознан — гейт промолчит");
    assert.ok(intent.matches.length > 0);
  });

  it("AB-01: обычный отчёт без обещания новой сущности не пропускает дальше", () => {
    const intent = detectIntent(REPORT);
    assert.equal(intent.promise, false, "отчёт принят за велосипед — модель зовётся зря");
  });

  it("AB-01: отрицание «не ввожу» считается обещанием — ступень 1 решает модель", () => {
    // Ступень 1 нарочно грубая: она отсеивает, а не судит. Пусть отсечёт лишнее,
    // модель потом ответит «нет». Обратное поведение опаснее: пропустит велосипед.
    assert.equal(detectIntent(FIXED).promise, true);
  });

  it("AB-01: глагол и существительное в разных предложениях не дают совпадения", () => {
    const text = "Сделал правку. Модуль уже есть в проекте, я его не трогал.";
    assert.equal(detectIntent(text).promise, false, "пара через всё сообщение — ложное срабатывание");
  });

  it("AB-01: пустой текст — нет обещания", () => {
    assert.equal(detectIntent("").promise, false);
    assert.equal(detectIntent("   \n  ").promise, false);
  });

  it("AB-01: законная новая работа тоже проходит отсев и уходит в модель", () => {
    const text = "Сделаю хук ~/.claude/hooks/anti-bike-stop.mjs: получает событие Stop и пишет замеры.";
    // Ступень 1 не различает законное и велосипед — это работа ступени 3.
    // Тест закрепляет, что и законное обещание не отсекается молча.
    assert.equal(detectIntent(text).promise, true);
  });
});

/**
 * Ступень 1: обещает ли текст завести новую сущность. Без модели, без сети.
 *
 * Это отсев, а не решение. Его работа — не пустить к модели те ходы, где писать
 * нечего. Ложный пропуск тут дешевле ложного срабатывания: ход уйдёт в модель
 * и получит «нет».
 *
 * Почему глагол плюс существительное, а не слово «велосипед»: на замерах вопрос
 * «это велосипед?» дал обратный ответ, а поиск обещания сущности — верный.
 *
 * Формы глаголов заданы регулярками, а не основами: первый прогон показал, что
 * основа «введ» не ловит «ввести» и «ввожу». Русская морфология тут важна —
 * без неё ступень 1 пропускает ровно те ходы, ради которых сделана.
 */

/**
 * Глаголы, которыми агент объявляет, что сейчас что-то заведёт.
 *
 * Формы: инфинитив, первое лицо будущего и настоящего времени. Прошедшее время
 * («сделал», «ввёл») сюда не входит: это отчёт о готовом, а не обещание.
 */
const VERB_PATTERN =
  /(введ(у|ём|ем|ёт|ет)?|ввести|введу|ввожу|вводить|добав(лю|ит|ить|ляю)|созда(м|ю|ть|ёт)|предлаг(аю|ать)|предложу|завест[иь]|заведу|напиш[уе]|написать|реализу(ю|ем|й)?|вынес(у|ти)?|собер(у|ём)?|собрать|определ(ю|ить)|постро(ю|ить)|сдела(ю|ть|ем))/i;

/**
 * Сущности, которые означают новый код в проекте.
 *
 * Список узкий нарочно: широкие слова («модель», «тест», «шаг») есть почти в каждом
 * отчёте, и ступень 1 перестала бы отсеивать.
 */
const NOUN_PATTERN =
  /(класс|объект|датакласс|dataclass|слой|прослойк|обёртк|обертк|абстракци|контейнер|адаптер|менеджер|раннер|сервис|модул|хелпер|утилит|переключател|хук|скрипт|обработчик|валидатор|чекер|порт[ауы]?\b)/i;

export interface Intent {
  /** Есть ли в тексте обещание завести новую сущность. */
  promise: boolean;
  /** Что именно нашлось: нужно для сообщения и для замеров. */
  matches: string[];
}

/**
 * Ищет в тексте обещание новой сущности.
 *
 * Условие — глагол и существительное в пределах одного предложения.
 * Пара через всё сообщение даёт ложные срабатывания: отчёт «я сделал X» и
 * отдельно «модуль Y уже есть» не обещают новую сущность.
 */
export function detectIntent(text: string): Intent {
  const matches: string[] = [];
  // Предложения режем по точке, восклицательному, вопросительному и переводу строки.
  for (const sentence of text.split(/(?<=[.!?])\s+|\n+/)) {
    const verb = VERB_PATTERN.exec(sentence);
    if (!verb) continue;
    const noun = NOUN_PATTERN.exec(sentence);
    if (!noun) continue;
    matches.push(`${verb[0].toLowerCase()}…${noun[0].toLowerCase()}`);
  }
  return { promise: matches.length > 0, matches };
}

/**
 * Клиент jscpd в режиме MCP.
 *
 * Замеры 2026-11-01 на пакете `carousel/` (92 файла):
 *   старт сервера (initialize)            856–1430 мс
 *   check_duplication первый раз           11–148 мс
 *   check_duplication повторно               1–11 мс
 *   check_current_directory (перескан)        7–68 мс
 *   для сравнения, CLI -—changed --baseline  5706 мс
 *
 * Поэтому сервер держим живым и проверяем фрагменты, а не сканируем репозиторий
 * на каждом ходе.
 */

import { spawn, type ChildProcessWithoutNullStreams } from "node:child_process";

export interface Duplication {
  kind: string;
  fileA: string;
  startA: number;
  endA: number;
  fileB: string;
  startB: number;
  endB: number;
  lines: number;
  tokens: number;
}

export interface DuplicationAnswer {
  count: number;
  duplications: Duplication[];
}

interface Pending {
  resolve: (value: unknown) => void;
  reject: (error: Error) => void;
}

/** Минимальный клиент MCP поверх stdio. Один процесс на репозиторий. */
export class JscpdMcp {
  private child: ChildProcessWithoutNullStreams | null = null;
  private buffer = "";
  private nextId = 1;
  private pending = new Map<number, Pending>();

  constructor(private readonly path: string) {}

  /** Поднимает сервер один раз. Повторный вызов ничего не делает. */
  async start(): Promise<void> {
    if (this.child) return;
    const child = spawn("jscpd", ["--mcp", this.path], { shell: true, windowsHide: true });
    this.child = child;
    child.stdout.on("data", (chunk: Buffer) => this.onData(chunk.toString("utf8")));
    child.stderr.on("data", () => {
      /* прогресс скана идёт в stderr, он тут не нужен */
    });
    await this.request("initialize", {
      protocolVersion: "2024-11-05",
      capabilities: {},
      clientInfo: { name: "anti-bike", version: "0.1.0" },
    });
    this.notify("notifications/initialized");
  }

  private onData(text: string): void {
    this.buffer += text;
    let index = this.buffer.indexOf("\n");
    while (index !== -1) {
      const line = this.buffer.slice(0, index).trim();
      this.buffer = this.buffer.slice(index + 1);
      index = this.buffer.indexOf("\n");
      if (line === "") continue;
      let message: { id?: number; result?: unknown; error?: { message?: string } };
      try {
        message = JSON.parse(line) as typeof message;
      } catch {
        continue;
      }
      if (typeof message.id !== "number") continue;
      const waiter = this.pending.get(message.id);
      if (!waiter) continue;
      this.pending.delete(message.id);
      if (message.error) waiter.reject(new Error(message.error.message ?? "ошибка MCP"));
      else waiter.resolve(message.result);
    }
  }

  request(method: string, params: unknown): Promise<unknown> {
    const child = this.child;
    if (!child) return Promise.reject(new Error("сервер не запущен"));
    const id = this.nextId++;
    const payload = JSON.stringify({ jsonrpc: "2.0", id, method, params });
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      child.stdin.write(`${payload}\n`);
    });
  }

  notify(method: string): void {
    this.child?.stdin.write(`${JSON.stringify({ jsonrpc: "2.0", method })}\n`);
  }

  /** Проверка фрагмента кода без пересканирования репозитория. */
  async check(code: string, format: string): Promise<DuplicationAnswer> {
    const result = (await this.request("tools/call", {
      name: "check_duplication",
      arguments: { code, format, kinds: ["exact", "renamed", "similar"] },
    })) as { content?: { text?: string }[] };
    const text = result.content?.[0]?.text ?? "";
    try {
      const parsed = JSON.parse(text) as DuplicationAnswer;
      return { count: parsed.count ?? 0, duplications: parsed.duplications ?? [] };
    } catch {
      throw new Error(`check_duplication вернул не JSON: ${text.slice(0, 200)}`);
    }
  }

  close(): void {
    this.child?.stdin.end();
    this.child?.kill();
    this.child = null;
  }
}

/**
 * Ступень 2 через MCP (AB-02, AB-03, AB-04).
 *
 * Проверяется на настоящем jscpd и настоящей фикстуре: поддельный ответ
 * не доказывает, что гейт увидит настоящий велосипед.
 */

import assert from "node:assert/strict";
import { readdir, readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
