    assert.ok(answer.count >= 1, "настоящий велосипед не найден");
    const files = answer.duplications.map((row) => row.fileB);
    assert.ok(
      files.some((file) => file.includes("existing.py")),
      `адрес не указывает на существующий код: ${files.join(", ")}`,
