/**
 * Список готового: что уже есть в проекте и в установленных библиотеках.
 *
 * Измерено 2026-11-01: без этого списка вопрос «повторяет ли готовое» не имеет
 * предмета сравнения. Drex-Max на настоящем велосипеде дал 0,05 без списка и 0,97
 * со списком; на исправленном ходе — 0,16 и 0,006.
 *
 * Список собирает код, а не модель: пересказ модели тут не годится, иначе гейт
 * судит по слухам о проекте.
 */

import { readdir, readFile } from "node:fs/promises";
import { basename, join } from "node:path";

export interface ReadyContext {
  /** Модули пакета: имя и первая строка docstring. */
  modules: { name: string; purpose: string }[];
  /** Установленные библиотеки с версиями. */
  libraries: { name: string; version: string }[];
  /** Готовый текст для модели. */
  markdown: string;
}

/** Сколько модулей и библиотек включать: длинный список размывает внимание. */
const MAX_MODULES = 40;
const MAX_LIBRARIES = 30;

/** Имя и назначение модуля по docstring. */
async function describeModule(path: string): Promise<{ name: string; purpose: string }> {
  let purpose = "";
  try {
    const head = await readFile(path, "utf8");
    const match = /^\s*(?:"""|''')([\s\S]*?)(?:"""|''')/.exec(head);
    if (match) purpose = match[1].trim().split("\n")[0].trim();
  } catch {
    purpose = "";
  }
  return { name: basename(path, ".py"), purpose: purpose.slice(0, 120) };
}

/** Модули пакета: `.py` в корне и в узлах, без тестов. */
export async function readModules(packageDir: string): Promise<{ name: string; purpose: string }[]> {
  const found: { name: string; purpose: string }[] = [];
  async function walk(dir: string, depth: number): Promise<void> {
    if (depth > 3 || found.length >= MAX_MODULES) return;
    let entries;
    try {
      entries = await readdir(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      if (found.length >= MAX_MODULES) return;
      if (entry.name.startsWith(".") || entry.name === "__pycache__") continue;
      const full = join(dir, entry.name);
      if (entry.isDirectory()) {
        await walk(full, depth + 1);
      } else if (entry.name.endsWith(".py") && !entry.name.startsWith("test_")) {
        found.push(await describeModule(full));
      }
    }
  }
  await walk(packageDir, 0);
  return found;
}

/** Версии библиотек из lock-файла или из `node_modules`/`site-packages`. */
export async function readLibraries(lockPath: string): Promise<{ name: string; version: string }[]> {
  const libraries: { name: string; version: string }[] = [];
  let text: string;
  try {
    text = await readFile(lockPath, "utf8");
  } catch {
    return libraries;
  }
  // Формат uv.lock: [[package]]\nname = "x"\nversion = "1.2.3"
  const blocks = text.split("[[package]]");
  for (const block of blocks) {
    if (libraries.length >= MAX_LIBRARIES) break;
    const name = /^\s*name\s*=\s*"([^"]+)"/m.exec(block);
    const version = /^\s*version\s*=\s*"([^"]+)"/m.exec(block);
    if (name && version) libraries.push({ name: name[1], version: version[1] });
  }
  return libraries;
}

/** Собирает список и переводит его в текст для модели. */
export async function buildReadyContext(
  packageDir: string,
  lockPath: string,
): Promise<ReadyContext> {
  const [modules, libraries] = await Promise.all([readModules(packageDir), readLibraries(lockPath)]);
  const lines = ["Что уже есть в проекте и в установленных библиотеках:"];
  if (modules.length > 0) {
    lines.push("\nМодули проекта:");
    for (const module of modules) {
      lines.push(module.purpose ? `- ${module.name}: ${module.purpose}` : `- ${module.name}`);
    }
  }
  if (libraries.length > 0) {
    lines.push("\nУстановленные библиотеки:");
    lines.push(libraries.map((library) => `${library.name} ${library.version}`).join(", "));
  }
  return { modules, libraries, markdown: lines.join("\n") };
}

/**
 * Ступень 3: суждение модели «повторяет ли текст готовое».
 *
 * Модель nace-ai/drex-max — family decision на OpenRouter, эндпоинт
 * POST /api/alpha/decisions, вопрос типа `noul` отдаёт вероятность 0..1.
 *
 * Замеры 2026-11-01, семь ходов настоящей сессии:
 *   позитив 0,974–0,992, трудный негатив 0,002–0,020, обычные негативы 0,001–0,019
 *   разброс между тремя прогонами ≤ 0,006, задержка 873–1300 мс
 *
 * Через chat/completions эта модель не работает: сервер отвечает 400
 * "is a decisions model and cannot be used with the chat/completions endpoint".
 */

const ENDPOINT = "https://openrouter.ai/api/alpha/decisions";

/**
 * Вопрос формулируется как задание, а не как ярлык.
 *
 * Проверено: «есть ли здесь предложение написать велосипед?» дало обратный ответ
 * (позитив 0,43, трудный негатив 0,77 у Jev). Работает задание найти в тексте
 * конкретное обещание новой сущности.
 */
const QUESTION = {
  type: "noul",
  instructions:
    "Дан текст агента и список того, что в проекте уже есть. Повторяет ли текст готовое — "
    + "предлагает ли он сделать то, что уже делает установленная библиотека или уже написано "
    + "в проекте?",
  criteria: {
    true: "текст предлагает свою сущность или слой для задачи, которую уже закрывает "
      + "названный механизм библиотеки или готовый код проекта",
    false: "текст не заводит ничего своего; либо заводит то, чего в списке готового нет "
      + "и что библиотека делать не умеет",
  },
} as const;

export interface Verdict {
  /** Вероятность «велосипед», 0..1. */
  score: number;
  /** Прошёл ли порог. */
  bike: boolean;
  /** Сколько занял вызов и сколько стоило. */
  ms: number;
  cost: number;
  inputTokens: number;
  outputTokens: number;
  /** Какое имя модели ответило: шлюз может подставить версию. */
  served: string;
}

export interface ClassifyOptions {
  /** Ключ OpenRouter. Не печатать и не логировать. */
  apiKey: string;
  /** Порог, выше которого считаем велосипедом. */
  threshold?: number;
  model?: string;
  timeoutMs?: number;
}

export const DEFAULT_THRESHOLD = 0.5;
export const DEFAULT_MODEL = "nace-ai/drex-max";

/** Проверяет, повторяет ли текст готовое. Список готового обязателен. */
export async function classify(
  text: string,
  ready: string,
  options: ClassifyOptions,
): Promise<Verdict> {
  const body = {
    model: options.model ?? DEFAULT_MODEL,
    state: `${ready}\n\nТекст агента:\n${text}`,
    questions: { bike: QUESTION },
  };
  const started = performance.now();
  const response = await fetch(ENDPOINT, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${options.apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(options.timeoutMs ?? 20_000),
  });
  const ms = Math.round(performance.now() - started);

  if (!response.ok) {
    const detail = (await response.text()).slice(0, 300);
    throw new Error(`decisions ответил ${response.status}: ${detail}`);
  }
  const payload = (await response.json()) as {
    model?: string;
    answers?: { bike?: { noul?: number } };
    usage?: { cost?: number; input_tokens?: number; output_tokens?: number };
  };
  const score = payload.answers?.bike?.noul;
  if (typeof score !== "number") {
    throw new Error(`в ответе нет answers.bike.noul: ${JSON.stringify(payload).slice(0, 300)}`);
  }
  return {
    score,
    bike: score >= (options.threshold ?? DEFAULT_THRESHOLD),
    ms,
    cost: payload.usage?.cost ?? 0,
    inputTokens: payload.usage?.input_tokens ?? 0,
    outputTokens: payload.usage?.output_tokens ?? 0,
    served: payload.model ?? "",
  };
}

/**
 * Решение гейта: пропустить, блокировать или промолчать при сбое.
 *
 * Правило одно: **сомнение не блокирует**. Ложная блокировка учит агента
 * игнорировать гейт, а пропуск стоит одного лишнего хода.
 */

import { classify, DEFAULT_THRESHOLD, type Verdict } from "./classify.ts";
import { detectIntent, type Intent } from "./intent.ts";
import type { Duplication } from "./mcp.ts";

export type VerdictKind = "skip" | "block" | "error";

export interface GateResult {
  kind: VerdictKind;
  /** Почему так решили: идёт в замеры и в причину блокировки. */
  reason: string;
  /** Что видит агент при блокировке. Пусто, когда пропускаем. */
  message: string;
  intent: Intent;
  score: number | null;
  duplications: Duplication[];
  ms: { parse: number; mcp: number; context: number; model: number };
  cost: number;
  /** Ошибка, если была: гейт не должен падать молча. */
  error: string | null;
}

export interface GateDeps {
  /** Проверка фрагмента через jscpd MCP. */
  checkClones: (code: string) => Promise<Duplication[]>;
  /** Список готового из проекта. */
  readyContext: () => Promise<string>;
  /** Суждение модели. */
  judge: (text: string, ready: string) => Promise<Verdict>;
  /** Язык фрагмента для jscpd. */
  format: string;
}

export interface GateInput {
  /** Текст последнего ответа агента. */
  message: string;
  /** Код, который агент написал или собирается написать. Может быть пустым. */
  code: string;
  /** Был ли уже блок в этом ходе: тогда не гоняем второй раз. */
  stopHookActive: boolean;
  threshold?: number;
}

/** Одна строка причины для блокировки: адрес кода или механизм. */
function buildMessage(duplications: Duplication[], score: number): string {
  const lines = ["anti-bike: в ходе обещан новый код, который уже есть.", ""];
  if (duplications.length > 0) {
    lines.push("Уже есть:");
    for (const row of duplications.slice(0, 3)) {
      lines.push(`  ${row.file}:${row.fileStartLine} (${row.kind}, ${row.lines} строк)`);
    }
  }
  lines.push("");
  lines.push(
    duplications.length > 0
      ? "Возьми готовое или назови, чем твоё отличается."
      : "Сверься со списком готового и назови, чем твоё отличается.",
  );
  lines.push(`(уверенность ${score.toFixed(2)})`);
  return lines.join("\n");
}

/**
 * Главная функция. Порядок ступеней важен: каждая следующая дороже предыдущей,
 * поэтому при отказе на дешёвой дорогая не зовётся.
 */
export async function runGate(
  input: GateInput,
  deps: GateDeps,
): Promise<GateResult> {
  const empty = { parse: 0, mcp: 0, context: 0, model: 0 };
  const skip = (reason: string): GateResult => ({
    kind: "skip",
    reason,
    message: "",
    intent: { promise: false, matches: [] },
    score: null,
    duplications: [],
    ms: empty,
    cost: 0,
    error: null,
  });

  // AB-07: повторный Stop не гоняем — иначе блокировка зацикливается.
  if (input.stopHookActive) return skip("повторный Stop");

  // AB-01: дешёвый отсев до всякой сети.
  const parseStart = performance.now();
  const intent = detectIntent(input.message);
  const parseMs = Math.round(performance.now() - parseStart);
  if (!intent.promise) return { ...skip("нет обещания новой сущности"), intent, ms: { ...empty, parse: parseMs } };

  try {
    // Ступень 2: факт о коде. Пустой код — тоже ответ, а не ошибка.
    const mcpStart = performance.now();
    const duplications = input.code.trim() === "" ? [] : await deps.checkClones(input.code);
    const mcpMs = Math.round(performance.now() - mcpStart);

    // Список готового нужен модели, без него вопрос бессмыслен.
    const contextStart = performance.now();
    const ready = await deps.readyContext();
    const contextMs = Math.round(performance.now() - contextStart);

    // Ступень 3: суждение.
    const verdict = await deps.judge(input.message, ready);

    // AB-06: порог. Ниже — пропуск, даже если клон нашёлся.
    if (!verdict.bike) {
      return {
        kind: "skip",
        reason: `ниже порога ${input.threshold ?? DEFAULT_THRESHOLD}`,
        message: "",
        intent,
        score: verdict.score,
        duplications,
        ms: { parse: parseMs, mcp: mcpMs, context: contextMs, model: verdict.ms },
        cost: verdict.cost,
        error: null,
      };
    }

    return {
      kind: "block",
      reason: duplications.length > 0 ? `клон ${duplications[0].file}:${duplications[0].fileStartLine}` : "механизм из списка готового",
      message: buildMessage(duplications, verdict.score),
      intent,
      score: verdict.score,
      duplications,
      ms: { parse: parseMs, mcp: mcpMs, context: contextMs, model: verdict.ms },
      cost: verdict.cost,
      error: null,
    };
  } catch (error) {
    // AB-10: сбой jscpd или модели не блокирует ход и не прячется.
    return {
      ...skip("сбой ступени"),
      intent,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * Решение гейта (AB-01, AB-05, AB-06, AB-07, AB-08, AB-10).
 *
 * Порты подменены скриптованными фейками: тесты не ходят в сеть и не тратят деньги.
 * Настоящий jscpd проверен отдельно в `mcp.test.ts`, настоящая фикстура — там же.
 */

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { runGate, type GateDeps } from "../src/gate.ts";
import type { Duplication } from "../src/mcp.ts";

const BIKE = "Один срез: RunContext — ввести объект «окружение шага» и провести через 16 узлов.";
const REPORT = "Верну цикл на место. Проверку выходных файлов оставил.";
const FIXED = "Штатный механизм беру: StateGraph с context_schema. Новый объект не ввожу.";

function duplication(): Duplication {
  return {
    file: "carousel/graph.py",
    fileStartLine: 235,
    fileEndLine: 250,
    snippetStartLine: 1,
    snippetEndLine: 16,
    kind: "renamed",
    lines: 16,
    tokens: 120,
  };
}

/** Обвязка, которая считает, какие ступени звали. */
function deps(overrides: Partial<GateDeps> = {}) {
  const calls = { clones: 0, context: 0, judge: 0 };
  const base: GateDeps = {
    checkClones: async () => {
      calls.clones += 1;
      return [duplication()];
    },
    readyContext: async () => {
      calls.context += 1;
      return "Модули проекта:\n- graph: граф прогона";
    },
    judge: async () => {
      calls.judge += 1;
      return { score: 0.97, bike: true, ms: 1100, cost: 0.00005, inputTokens: 900, outputTokens: 34, served: "nace-ai/drex-max" };
    },
    format: "python",
    ...overrides,
  };
  return { base, calls };
}

describe("гейт", () => {
  it("AB-01: ход без обещания не зовёт ни jscpd, ни модель", async () => {
    const { base, calls } = deps();
    const result = await runGate({ message: REPORT, code: "", stopHookActive: false }, base);
    assert.equal(result.kind, "skip");
    assert.equal(calls.clones, 0, "jscpd звали зря");
    assert.equal(calls.judge, 0, "модель звали зря");
  });

  it("AB-07: повторный Stop не гоняет проверку заново", async () => {
    const { base, calls } = deps();
    const result = await runGate({ message: BIKE, code: "", stopHookActive: true }, base);
    assert.equal(result.kind, "skip");
    assert.equal(result.reason, "повторный Stop");
    assert.equal(calls.judge, 0, "петля блокировок");
  });

  it("AB-05: модель получает список готового, а не один текст", async () => {
    const { base } = deps();
    let seenReady = "";
    let seenText = "";
    await runGate(
      { message: BIKE, code: "", stopHookActive: false },
      {
        ...base,
        judge: async (text, ready) => {
          seenText = text;
          seenReady = ready;
          return { score: 0.9, bike: true, ms: 1, cost: 0, inputTokens: 0, outputTokens: 0, served: "x" };
        },
      },
    );
    assert.ok(seenReady.includes("Модули проекта"), "список готового не передан");
    assert.ok(seenText.includes("RunContext"), "текст хода не передан");
  });

  it("AB-06: score ниже порога пропускается, даже когда клон найден", async () => {
    const { base } = deps({
      judge: async () => ({ score: 0.49, bike: false, ms: 1, cost: 0, inputTokens: 0, outputTokens: 0, served: "x" }),
    });
    const result = await runGate({ message: BIKE, code: "", stopHookActive: false }, base);
    assert.equal(result.kind, "skip", "порог не применён");
    assert.equal(result.duplications.length, 1, "клон найден, но решает порог");
  });

  it("AB-06: score ровно на пороге блокирует", async () => {
    const { base } = deps({
      judge: async () => ({ score: 0.5, bike: true, ms: 1, cost: 0, inputTokens: 0, outputTokens: 0, served: "x" }),
    });
    const result = await runGate({ message: BIKE, code: "", stopHookActive: false }, base);
    assert.equal(result.kind, "block");
  });

  it("AB-08: причина блокировки называет файл и строку", async () => {
    const { base } = deps();
    const result = await runGate({ message: BIKE, code: "class X: ...", stopHookActive: false }, base);
    assert.equal(result.kind, "block");
    assert.ok(result.message.includes("carousel/graph.py:235"), `адреса нет: ${result.message}`);
  });

  it("AB-08: без клона причина называет механизм, а не молчит", async () => {
    const { base } = deps({ checkClones: async () => [] });
    const result = await runGate({ message: BIKE, code: "", stopHookActive: false }, base);
    assert.equal(result.kind, "block");
    assert.ok(result.message.includes("списком готового"), `нет указания, что делать: ${result.message}`);
  });

  it("AB-10: сбой jscpd не блокирует ход и не прячется", async () => {
    const { base } = deps({ checkClones: async () => { throw new Error("jscpd не запустился"); } });
    const result = await runGate({ message: BIKE, code: "class X: ...", stopHookActive: false }, base);
    assert.equal(result.kind, "skip", "сбой инфраструктуры заблокировал агента");
    assert.match(result.error ?? "", /jscpd не запустился/);
  });

  it("AB-10: сбой модели не блокирует ход", async () => {
    const { base } = deps({ judge: async () => { throw new Error("decisions ответил 429"); } });
    const result = await runGate({ message: BIKE, code: "", stopHookActive: false }, base);
    assert.equal(result.kind, "skip");
    assert.match(result.error ?? "", /429/);
  });

  it("AB-09: замер идёт с раздельным временем слоёв", async () => {
    const { base } = deps();
    const result = await runGate({ message: BIKE, code: "class X: ...", stopHookActive: false }, base);
    assert.equal(typeof result.ms.parse, "number");
    assert.equal(typeof result.ms.mcp, "number");
    assert.equal(typeof result.ms.context, "number");
    assert.equal(typeof result.ms.model, "number");
  });

  it("исправленный ход проходит отсев, но порог его отпускает", async () => {
    const { base } = deps({
      judge: async () => ({ score: 0.02, bike: false, ms: 1, cost: 0, inputTokens: 0, outputTokens: 0, served: "x" }),
    });
    const result = await runGate({ message: FIXED, code: "", stopHookActive: false }, base);
    assert.equal(result.kind, "skip");
    assert.equal(result.score, 0.02);
  });
});

