/**
 * Живая проверка гейта целиком: jscpd MCP + список готового + Drex-Max.
 *
 * Запуск: node --experimental-strip-types scripts/live-check.ts
 * Платно: несколько вызовов модели на центы.
 */

import { readFile } from "node:fs/promises";
import { join } from "node:path";

import { classify } from "../src/classify.ts";
import { buildReadyContext } from "../src/context.ts";
import { runGate } from "../src/gate.ts";
import { JscpdMcp } from "../src/mcp.ts";

const REPO = "E:/repos/carousel-demo";
const CASES = join(import.meta.dirname, "..", "test", "fixtures", "turns.json");

interface Turn {
  id: string;
  label: "positive" | "hard_negative" | "negative";
  message: string;
  code: string;
}

function apiKey(): string {
  const key = process.env.OPENROUTER_API_KEY;
  if (!key) throw new Error("нет OPENROUTER_API_KEY в окружении");
  return key;
}

async function main(): Promise<void> {
  const turns = JSON.parse(await readFile(CASES, "utf8")) as Turn[];
  const ready = await buildReadyContext(join(REPO, "carousel"), join(REPO, "uv.lock"));
  console.log(`список готового: модулей ${ready.modules.length}, библиотек ${ready.libraries.length}`);
  console.log(`размер списка: ${ready.markdown.length} символов\n`);

  const mcp = new JscpdMcp(join(REPO, "carousel"));
  await mcp.start();
  const key = apiKey();

  let total = 0;
  try {
    for (const turn of turns) {
      const result = await runGate(
        { message: turn.message, code: turn.code, stopHookActive: false },
        {
          checkClones: async (code) => (await mcp.check(code, "python")).duplications,
          readyContext: async () => ready.markdown,
          judge: async (text, context) => classify(text, context, { apiKey: key }),
          format: "python",
        },
      );
      total += result.cost;
      console.log(`${turn.id.padEnd(9)} ${turn.label.padEnd(14)} ${result.kind.padEnd(6)} `
        + `score=${result.score === null ? "—" : result.score.toFixed(3).padEnd(6)} `
        + `клоны=${result.duplications.length} `
        + `ms=${result.ms.parse}/${result.ms.mcp}/${result.ms.context}/${result.ms.model}`);
      if (result.error) console.log(`   ошибка: ${result.error}`);
      if (result.kind === "block") {
        console.log(`   причина:\n${result.message.split("\n").map((line) => `     ${line}`).join("\n")}`);
      }
    }
  } finally {
    mcp.close();
  }
  console.log(`\nстоимость: $${total.toFixed(6)}`);
}

await main();

/**
 * Сравнение трёх видов списка готового на одном и том же ходе.
 *
 * Вопрос: почему настоящий список репозитория дал 0,077 там, где рукописный
 * список механизмов дал 0,97. Гипотеза — дело в составе списка, не в модели.
 */

import { readFile } from "node:fs/promises";
import { join } from "node:path";

import { classify } from "../src/classify.ts";
import { buildReadyContext } from "../src/context.ts";
import { detectIntent } from "../src/intent.ts";

const REPO = "E:/repos/carousel-demo";
const CASES = join(import.meta.dirname, "..", "test", "fixtures", "turns.json");

interface Turn {
  id: string;
  label: string;
  message: string;
  code: string;
}

/** Список механизмов: то, что проект реально использует, с названиями. */
const MECHANISMS = `Что уже есть в проекте и в установленных библиотеках:
- langgraph 1.2.12: StateGraph(state_schema, context_schema=Context), Runtime[Context] в узле —
  штатная передача неизменных зависимостей в узлы графа.
- langgraph: AsyncSqliteSaver + durability="sync" — чекпоинты, продолжение, перемотка на шаг.
- langgraph: Command(goto=[Send(...)]) — переделать только затронутые карточки.
- langgraph: interrupt — остановка прогона и продолжение после ответа.
- deepagents 0.7.19: агент с ToolStrategy отвечает схемой.
- В проекте: порты typing.Protocol на внешний мир, Pydantic-схема на каждый контракт,
  общий шаг calls/ для платных вызовов с кешем по хешу входа.`;

async function main(): Promise<void> {
  const key = process.env.OPENROUTER_API_KEY;
  if (!key) throw new Error("нет OPENROUTER_API_KEY");

  const turns = JSON.parse(await readFile(CASES, "utf8")) as Turn[];
  const picked = turns.filter((turn) => ["[20252]", "[20497]", "[code]"].includes(turn.id));
  const ready = await buildReadyContext(join(REPO, "carousel"), join(REPO, "uv.lock"));

  // Третий вариант: модули пакета с их назначением, но без чужих библиотек.
  const modulesOnly = ready.markdown.split("\nУстановленные библиотеки:")[0];

  const variants: Record<string, string> = {
    "1 механизмы с названиями": MECHANISMS,
    "2 модули проекта, 40 шт": modulesOnly,
    "3 модули + библиотеки": ready.markdown,
    "4 без списка": "",
  };

  let spend = 0;
  for (const [name, context] of Object.entries(variants)) {
    console.log(`\n=== ${name} (${context.length} символов) ===`);
    for (const turn of picked) {
      const intent = detectIntent(turn.message);
      if (!intent.promise) {
        console.log(`  ${turn.id.padEnd(9)} ${turn.label.padEnd(14)} отсечён ступенью 1`);
        continue;
      }
      const verdict = await classify(turn.message, context, { apiKey: key });
      spend += verdict.cost;
      const mark = verdict.bike ? "БЛОК" : "    ";
      console.log(`  ${turn.id.padEnd(9)} ${turn.label.padEnd(14)} ${mark} ${verdict.score.toFixed(3)}`);
    }
  }
  console.log(`\nстоимость: $${spend.toFixed(6)}`);
}

await main();

/**
 * Список готового: что проект уже импортирует из установленных библиотек.
 *
 * Замер 2026-11-01, один и тот же ход `[20252]`, Drex-Max, порог 0,5:
 *   список механизмов с именами (658 символов)  0,892  — верно
 *   список модулей пакета, 40 штук             0,108  — промах
 *   модули плюс библиотеки                     0,077  — промах
 *   без списка                                 0,049  — промах
 *
 * Вывод: имена модулей проекта размывают ответ. Модели нужны названия
 * механизмов, которые она может сопоставить с предложением: `context_schema`,
 * `AsyncSqliteSaver`, `Command`, `interrupt`.
 *
 * Поэтому список собирается из импортов, а не из оглавления пакета.
 */

import { readdir, readFile } from "node:fs/promises";
import { join } from "node:path";

export interface Imported {
  /** Имя установленной библиотеки. */
  library: string;
  /** Имена, которые проект из неё берёт. */
  names: string[];
}

export interface ReadyContext {
  imports: Imported[];
  /** Готовый текст для модели. */
  markdown: string;
  /** Сколько символов попало в текст: длинный список размывает ответ. */
  size: number;
}

/** Имена, которые не несут смысла механизма: типы, исключения, служебное. */
const NOISE = /^(Any|Optional|Union|Literal|TypedDict|Protocol|Callable|Awaitable|Sequence|Mapping|Path|Decimal|datetime|timedelta)$/;

/** Стандартная библиотека: её механизмы модель знает без списка. */
const STDLIB = new Set([
  "__future__", "abc", "argparse", "asyncio", "base64", "collections", "contextlib", "copy",
  "csv", "dataclasses", "datetime", "decimal", "enum", "functools", "hashlib", "html", "io",
  "itertools", "json", "logging", "math", "os", "pathlib", "random", "re", "shutil", "signal",
  "sqlite3", "string", "subprocess", "sys", "tempfile", "textwrap", "time", "typing",
  "unicodedata", "urllib", "uuid", "warnings", "zipfile",
]);

/** Собирает импорты из всех `.py` под путём. */
async function collectImports(dir: string, into: Map<string, Set<string>>): Promise<void> {
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    if (entry.name.startsWith(".") || entry.name === "__pycache__") continue;
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      await collectImports(full, into);
      continue;
    }
    if (!entry.name.endsWith(".py") || entry.name.startsWith("test_")) continue;
    const text = await readFile(full, "utf8");
    // `from x.y import a, b` и `import x`
    for (const match of text.matchAll(/^from\s+([\w.]+)\s+import\s+\(?([^\n)]+)\)?/gm)) {
      const library = match[1].split(".")[0];
      if (STDLIB.has(library) || library.startsWith("carousel")) continue;
      const names = match[2]
        .split(",")
        .map((part) => part.trim().split(/\s+as\s+/)[0].trim())
        .filter((name) => name.length > 0 && !NOISE.test(name));
      if (names.length === 0) continue;
      const bucket = into.get(library) ?? new Set<string>();
      for (const name of names) bucket.add(name);
      into.set(library, bucket);
    }
  }
}

/** Версии библиотек из `uv.lock`. */
export async function readVersions(lockPath: string): Promise<Map<string, string>> {
  const versions = new Map<string, string>();
  let text: string;
  try {
    text = await readFile(lockPath, "utf8");
  } catch {
    return versions;
  }
  for (const block of text.split("[[package]]")) {
    const name = /^\s*name\s*=\s*"([^"]+)"/m.exec(block);
    const version = /^\s*version\s*=\s*"([^"]+)"/m.exec(block);
    if (name && version) versions.set(name[1].toLowerCase(), version[1]);
  }
  return versions;
}

/** Сколько имён на библиотеку включать: длинный список размывает ответ. */
const MAX_NAMES = 12;

/**
 * Собирает список готового.
 *
 * Порядок важен: сначала то, что проект реально импортирует, потом версия.
 * Библиотеки без версии в lock-файле всё равно попадают: имя механизма полезнее версии.
 */
export async function buildReadyContext(
  packageDir: string,
  lockPath: string,
): Promise<ReadyContext> {
  const found = new Map<string, Set<string>>();
  await collectImports(packageDir, found);
  const versions = await readVersions(lockPath);

  const imports: Imported[] = [...found.entries()]
    .map(([library, names]) => ({ library, names: [...names].slice(0, MAX_NAMES) }))
    .sort((left, right) => right.names.length - left.names.length);

  const lines: string[] = ["Что проект уже берёт из установленных библиотек:"];
  for (const entry of imports) {
    const version = versions.get(entry.library.toLowerCase());
    const head = version ? `${entry.library} ${version}` : entry.library;
    lines.push(`- ${head}: ${entry.names.join(", ")}`);
  }
  const markdown = lines.join("\n");
  return { imports, markdown, size: markdown.length };
}

import { buildReadyContext } from "../src/context.ts";

const ready = await buildReadyContext("E:/repos/carousel-demo/carousel", "E:/repos/carousel-demo/uv.lock");
console.log(`библиотек: ${ready.imports.length}, символов: ${ready.size}\n`);
console.log(ready.markdown);

