/**
 * Список возможностей проекта: что в нём уже умеет делать библиотека и сам код.
 *
 * Замеры 2026-11-01, один ход `[20252]`, Drex-Max, порог 0,5:
 *
 *   без списка                                        0,049  промах
 *   автосписок: модули пакета                         0,108  промах
 *   автосписок: имена импортов                        0,030  промах
 *   автосписок: docstring'и пакетов, 22 штуки         0,022  промах
 *   курируемый список возможностей, 720 символов      0,951  верно
 *
 * Корень: модель сравнивает **понятия**. В пакетах есть класс `StateGraph`, но
 * `context_schema` — его параметр, отдельного имени у него нет. Автосборка по
 * импортам и docstring'ам такое понятие не достаёт, а курируемая запись —
 * «StateGraph принимает state_schema и context_schema» — достаёт.
 *
 * Поэтому основной источник — файл `.anti-bike/capabilities.md` в репозитории:
 * его пишет человек или агент один раз на проект. Автосписок остаётся запасным.
 */

import { readFile } from "node:fs/promises";
import { join } from "node:path";

/** Где лежит курируемый список возможностей. */
export const CAPABILITIES_PATH = join(".anti-bike", "capabilities.md");

/** Сколько символов списка терпит модель: длинный размывает ответ. */
export const MAX_CAPABILITIES = 3000;

export interface Capabilities {
  /** Текст для модели. */
  markdown: string;
  /** Откуда взят: `file` — курируемый, `auto` — собран из пакетов, `none` — пусто. */
  source: "file" | "auto" | "none";
  size: number;
}

/**
 * Читает курируемый список, если он есть.
 *
 * Размер ограничен: список на 10 тысяч символов модель не читает как список
 * возможностей, а тонет в нём.
 */
export async function readCapabilities(repoRoot: string): Promise<string | null> {
  try {
    const text = await readFile(join(repoRoot, CAPABILITIES_PATH), "utf8");
    const trimmed = text.trim();
    if (trimmed === "") return null;
    return trimmed.slice(0, MAX_CAPABILITIES);
  } catch {
    return null;
  }
}

/**
 * Собирает список возможностей: курируемый, если он есть, иначе запасной.
 *
 * Запасной путь — автосписок из импортов и docstring'ов. Он слабее (замеры выше),
 * но лучше пустоты: без списка вопрос «повторяет ли готовое» не имеет предмета.
 */
export async function resolveCapabilities(
  repoRoot: string,
  fallback: () => Promise<string>,
): Promise<Capabilities> {
  const curated = await readCapabilities(repoRoot);
  if (curated !== null) {
    return { markdown: curated, source: "file", size: curated.length };
  }
  const generated = await fallback();
  if (generated.trim() === "") {
    return { markdown: "", source: "none", size: 0 };
  }
  return { markdown: generated, source: "auto", size: generated.length };
}

/**
 * Список возможностей (AB-05).
 *
 * Замеры показали, что источник списка решает больше, чем модель: автосборка
 * даёт 0,022, курируемый файл — 0,951. Тесты закрепляют приоритет источника.
 */

import assert from "node:assert/strict";
import { mkdtemp, mkdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { describe, it } from "node:test";
import { fileURLToPath } from "node:url";

import {
  CAPABILITIES_PATH,
  MAX_CAPABILITIES,
  readCapabilities,
  resolveCapabilities,
} from "../src/capabilities.ts";

const HERE = dirname(fileURLToPath(import.meta.url));
const FIXTURE_REPO = join(HERE, "fixtures", "bike-repo");

async function tempRepo(): Promise<string> {
  return mkdtemp(join(tmpdir(), "anti-bike-caps-"));
}

describe("список возможностей", () => {
  it("AB-05: курируемый файл проекта читается и содержит механизмы", async () => {
    const text = await readCapabilities(FIXTURE_REPO);
    assert.ok(text !== null, "файл проекта не прочитан");
    assert.ok(text.includes("context_schema"), "в списке нет механизма, ради которого он нужен");
  });

  it("AB-05: курируемый список главнее автосписка", async () => {
    const resolved = await resolveCapabilities(FIXTURE_REPO, async () => "АВТОСПИСОК");
    assert.equal(resolved.source, "file", "автосписок перебил курируемый");
    assert.ok(resolved.markdown.includes("context_schema"));
  });

  it("AB-05: без курируемого файла берётся автосписок, а не пустота", async () => {
    const repo = await tempRepo();
    try {
      const resolved = await resolveCapabilities(repo, async () => "АВТОСПИСОК");
      assert.equal(resolved.source, "auto");
      assert.equal(resolved.markdown, "АВТОСПИСОК");
    } finally {
      await rm(repo, { recursive: true, force: true, maxRetries: 20, retryDelay: 250 });
    }
  });

  it("AB-05: пустой файл не считается списком", async () => {
    const repo = await tempRepo();
    try {
      await mkdir(join(repo, ".anti-bike"), { recursive: true });
      await writeFile(join(repo, CAPABILITIES_PATH), "   \n\n  ");
      const resolved = await resolveCapabilities(repo, async () => "АВТОСПИСОК");
      assert.equal(resolved.source, "auto", "пустой файл принят за список");
    } finally {
      await rm(repo, { recursive: true, force: true, maxRetries: 20, retryDelay: 250 });
    }
  });

  it("AB-05: длинный список обрезается, а не уходит модели целиком", async () => {
    const repo = await tempRepo();
    try {
      await mkdir(join(repo, ".anti-bike"), { recursive: true });
      await writeFile(join(repo, CAPABILITIES_PATH), "х".repeat(MAX_CAPABILITIES * 2));
      const resolved = await resolveCapabilities(repo, async () => "");
      assert.equal(resolved.size, MAX_CAPABILITIES);
    } finally {
      await rm(repo, { recursive: true, force: true, maxRetries: 20, retryDelay: 250 });
    }
  });
});

/**
 * Собирает ходы из настоящих транскриптов Claude Code для разметки.
 *
 * Берём только текст ответов ассистента (то, что видит Stop-хук) и код,
 * который агент записал в этом же ходе через Write/Edit. Ходы, отсечённые
 * ступенью 1, в набор не входят: их гейт и так не пустит к модели.
 *
 * Запуск: node --experimental-strip-types scripts/extract-turns.ts <каталог-проекта> <имя-файла>
 */

import { readdir, readFile, writeFile } from "node:fs/promises";
import { basename, join } from "node:path";

import { detectIntent } from "../src/intent.ts";

interface Raw {
  type?: string;
  message?: { role?: string; content?: unknown };
}

interface Turn {
  /** Стабильный ключ для разметки. */
  id: string;
  /** Текст ответа агента: он же вход ступени 3. */
  message: string;
  /** Код, записанный в этом ходе. Пусто, если ход ничего не писал. */
  code: string;
  /** Имена файлов, которые тронул ход. */
  files: string[];
  /** Разметка человеком: null — ещё не размечено. */
  label: "bike" | "ok" | null;
  /** Почему так: заполняет человек. */
  note: string;
}

/** Текст блоков ответа плюс код из Write/Edit того же сообщения. */
function readRecord(record: Raw): { text: string; code: string; files: string[] } {
  const content = record.message?.content;
  if (!Array.isArray(content)) return { text: "", code: "", files: [] };
  const texts: string[] = [];
  const codes: string[] = [];
  const files: string[] = [];
  for (const block of content) {
    if (!block || typeof block !== "object") continue;
    const item = block as { type?: string; text?: string; name?: string; input?: Record<string, unknown> };
    if (item.type === "text" && typeof item.text === "string") texts.push(item.text);
    if (item.type === "tool_use" && (item.name === "Write" || item.name === "Edit" || item.name === "MultiEdit")) {
      const input = item.input ?? {};
      if (typeof input.file_path === "string") files.push(input.file_path);
      if (typeof input.content === "string") codes.push(input.content);
      if (typeof input.new_string === "string") codes.push(input.new_string);
    }
  }
  return { text: texts.join("\n").trim(), code: codes.join("\n"), files };
}

async function main(): Promise<void> {
  const [projectDir, outName] = process.argv.slice(2);
  if (!projectDir || !outName) {
    console.error("нужно: scripts/extract-turns.ts <каталог-проекта> <файл-выхода>");
    process.exit(2);
  }
  const files = (await readdir(projectDir)).filter((name) => name.endsWith(".jsonl"));
  const turns: Turn[] = [];

  for (const file of files) {
    const path = join(projectDir, file);
    let lines: string;
    try {
      lines = await readFile(path, "utf8");
    } catch {
      continue;
    }
    for (const [index, line] of lines.split("\n").entries()) {
      if (line.trim() === "") continue;
      let record: Raw;
      try {
        record = JSON.parse(line) as Raw;
      } catch {
        continue;
      }
      if (record.type !== "assistant") continue;
      const { text, code, files: touched } = readRecord(record);
      if (text === "") continue;
      // Ходы без обещания новой сущности до модели не доходят — в наборе не нужны.
      if (!detectIntent(text).promise) continue;
      turns.push({
        id: `${basename(file, ".jsonl").slice(0, 8)}-${index}`,
        message: text,
        code,
        files: touched,
        label: null,
        note: "",
      });
    }
  }

  const out = join(import.meta.dirname, "..", "bench", outName);
  await writeFile(out, JSON.stringify(turns, null, 2), "utf8");
  const withCode = turns.filter((turn) => turn.code !== "").length;
  console.log(`ходов: ${turns.length}, из них с кодом: ${withCode}`);
  console.log(`записано: ${out}`);
}

await main();

