import json
import os
import urllib.error
import urllib.request

BASE = "https://aipomogator.ru/go/v1"
MODEL = "openrouter/anthropic/claude-opus-5"
TOKEN = os.environ.get("AIPOMOGATOR_TOKEN") or os.environ.get("AIPOMOGATOR_API_KEY") or ""

SCHEMA = {
    "type": "object",
    "properties": {"answer": {"type": "string", "enum": ["zebra"]}},
    "required": ["answer"],
    "additionalProperties": False,
}


def body(provider: dict[str, object] | None) -> dict[str, object]:
    payload: dict[str, object] = {
        "model": MODEL,
        "messages": [{"role": "user", "content": "Name the word hello. Answer field only."}],
        "max_tokens": 64,
        "stream": False,
        "response_format": {
            "type": "json_schema",
            "json_schema": {"name": "probe_answer", "strict": True, "schema": SCHEMA},
        },
    }
    if provider is not None:
        payload["provider"] = provider
    return payload


def post(payload: dict[str, object]) -> tuple[int, str]:
    request = urllib.request.Request(
        f"{BASE}/chat/completions",
        data=json.dumps(payload).encode("utf-8"),
        headers={"Authorization": f"Bearer {TOKEN}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=120) as response:
            return response.status, response.read().decode("utf-8")
    except urllib.error.HTTPError as error:
        return error.code, error.read().decode("utf-8", errors="replace")


def show(label: str, status: int, text: str) -> None:
