"""План карусели: `plans/<k>.json` (ARCHITECTURE §3, «Узел story»; REQUIREMENTS DR-11, FR-30, CR-11).

Роли карточек, `Beat` и `Plan`. Плана до текста нет: число карточек, роли и работу называет писатель,
а `Plan` код выводит из готового текста (`carousel/free_story.py`). План описывает написанное и
ничего не требует; его читают visuals, design, directions, судья и страница выбора. Жёсткая здесь
только форма: число карточек, порядок ролей, номера тезисов в границах разбора, картинки. Ни сети,
ни библиотек графа.
"""

from __future__ import annotations

import math
from collections.abc import Sequence
from typing import Literal, Self, get_args

from pydantic import field_validator, model_validator

from carousel.schemas import MIN_CARDS, Analysis, CardLimits, Contract, Text
from carousel.validation import summarize

Role = Literal[
    "cover", "lead", "mechanism", "numbers", "comparison", "example", "quote", "steps",
    "code", "caveat", "context", "why_now", "wider", "verdict", "finale",
]  # fmt: skip
ROLES: tuple[Role, ...] = get_args(Role)

# Как роль называется в раскадровке для судьи и автора.
ROLE_LABELS: dict[Role, str] = {
    "cover": "обложка",
    "lead": "лид",
    "mechanism": "механизм",
    "numbers": "цифры",
    "comparison": "сравнение",
    "example": "пример",
    "quote": "цитата",
    "steps": "шаги",
    "code": "код",
    "caveat": "подвох",
    "context": "контекст",
    "why_now": "зачем сейчас",
    "wider": "шире",
    "verdict": "вывод",
    "finale": "финал: мост в пост",
}

DEFAULT_PICTURE_SHARE = 0.67  # доля карточек с картинкой не выше: `[limits] picture_share`


class Beat(Contract):
    """Карточка плана: роль, работа и тезисы, на которые опирается текст (DR-11).

    `carries` — номера тезисов разбора с нуля, чей якорь перекрыл якорь карточки.
    """

    role: Role
    job: Text
    carries: list[int]
    picture: bool

    @model_validator(mode="after")
    def _no_number_twice(self) -> Self:
        repeated = sorted({n for n in self.carries if self.carries.count(n) > 1})
        if repeated:
            raise ValueError(f"carries: номер назван повторно: {repeated}")
        if any(n < 0 for n in self.carries):
            raise ValueError("carries: номер не бывает отрицательным")
        return self


def _numbers(numbers: Sequence[int]) -> str:
    """Номера через запятую: «1, 5»."""
    return ", ".join(str(number) for number in numbers)


def role_problems(roles: Sequence[Role]) -> list[str]:
    """Обложка первая, финал последний, каждая по разу, лид не больше одного (DR-11)."""
    problems: list[str] = []
    if roles[0] != "cover":
        problems.append(f"первая карточка — cover, а не {roles[0]}")
    if roles[-1] != "finale":
        problems.append(f"последняя карточка — finale, а не {roles[-1]}")
    if roles.count("cover") != 1:
        problems.append("cover стоит один раз, первой")
    if roles.count("finale") != 1:
        problems.append("finale стоит один раз, последней")
    if roles.count("lead") > 1:
        problems.append("lead не больше одного")
    return problems


def count_problems(count: int, limits: CardLimits) -> list[str]:
    """Число карточек в границах запуска или ровно столько, сколько просил автор (FR-30)."""
    if limits.exact is not None and count != limits.exact:
        return [f"автор просил ровно {limits.exact} карточек, получено {count}"]
    if count < MIN_CARDS:
        return [f"карточек не меньше {MIN_CARDS}, получено {count}"]
    if count > limits.max_cards:
        return [f"карточек не больше {limits.max_cards}, получено {count}"]
    return []


def picture_cap(share: float, count: int) -> int:
    """Наибольшее число карточек с картинкой при доле `share` (DR-11, FR-30): доля не выше предела,
    поэтому округление вниз. Обложке картинка нужна всегда, так что меньше одной не бывает."""
    return max(1, math.floor(round(share * count, 9)))


def picture_problems(pictures: Sequence[bool], share: float) -> list[str]:
    """У обложки картинка, картинок не больше доли `share` (DR-11)."""
    problems: list[str] = []
    if not pictures[0]:
        problems.append("у обложки нужна картинка")
    cap = picture_cap(share, len(pictures))
    if (count := sum(pictures)) > cap:
        problems.append(f"картинок {count} из {len(pictures)}, не больше {cap}")
    return problems


class Plan(Contract):
    """План направления: сколько карточек и почему, что на каждой, мост в пост (DR-11, FR-30).

    Число карточек — длина `beats`, отдельного поля нет. `left_for_post` — сильные тезисы, которых
    не несёт ни одна карточка: они служат причиной открыть пост (CR-10).
    """

    reason: Text
    bridge: Text
    left_for_post: list[int]
    beats: list[Beat]

    @property
    def count(self) -> int:
        return len(self.beats)

    @field_validator("beats")
    @classmethod
    def _enough_beats(cls, value: list[Beat]) -> list[Beat]:
        if len(value) < MIN_CARDS:
            raise ValueError(f"в плане не меньше {MIN_CARDS} карточек, получено {len(value)}")
        return value

    @model_validator(mode="after")
    def _roles_stand_in_order(self) -> Self:
        if problems := role_problems([beat.role for beat in self.beats]):
            raise ValueError(problems[0])
        return self

    @classmethod
    def bound_to(
        cls,
        analysis: Analysis,
        limits: CardLimits,
        *,
        picture_share: float = DEFAULT_PICTURE_SHARE,
    ) -> type[Self]:
        """Схема плана для этого поста: число карточек в лимитах, номера тезисов в границах разбора,
        картинка у обложки и доля картинок в пределе."""

        class Bound(cls):  # type: ignore[valid-type, misc]
            __doc__ = cls.__doc__  # описание схемы берётся из докстринга, а он не наследуется

            @model_validator(mode="after")
            def _fits_the_breakdown(self) -> Self:
                problems = [
                    *count_problems(self.count, limits),
                    *_index_problems(self, analysis),
                    *picture_problems([beat.picture for beat in self.beats], picture_share),
                ]
                if problems:
                    raise ValueError(summarize(problems))
                return self

        Bound.__name__ = Bound.__qualname__ = cls.__name__
        return Bound

    def validate_indices(self, analysis: Analysis) -> None:
        """Номера тезисов прочитанного плана должны существовать в разборе."""
        if problems := _index_problems(self, analysis):
            raise ValueError(summarize(problems))

    def carried(self) -> list[int]:
        """Тезисы, которые несут карточки, без повторов: так страница выбора показывает фокус."""
        return sorted({index for beat in self.beats for index in beat.carries})

    def to_markdown(self, analysis: Analysis) -> str:
        """План словами разбора: номера раскрыты в тексты, поста читать не надо (агенту оформления,
        концепту для автора)."""
        lines = [
            f"Карточек: {self.count}",
            f"Причина: {self.reason}",
            f"Мост в пост: {self.bridge}",
        ]
        if self.left_for_post:
            left = "; ".join(analysis.theses[i].text for i in self.left_for_post)
            lines.append(f"Оставлено для поста: {left}")
        for number, beat in enumerate(self.beats, 1):
            lines += ["", f"Карточка {number}. {beat.role} — {beat.job}"]
            if beat.carries:
                lines.append(
                    "Несёт тезисы: " + "; ".join(analysis.theses[i].text for i in beat.carries)
                )
            lines.append(f"С картинкой: {'да' if beat.picture else 'нет'}")
        return "\n".join(lines) + "\n"


def _index_problems(plan: Plan, analysis: Analysis) -> list[str]:
    size = len(analysis.theses)
    problems = [
        f"beats[{number}].carries: номера {outside} вне разбора ({size})"
        for number, beat in enumerate(plan.beats)
        if (outside := [n for n in beat.carries if n >= size])
    ]
    outside = [n for n in plan.left_for_post if not 0 <= n < size]
    if outside:
        problems.append(f"left_for_post: номера {outside} вне тезисов разбора ({size})")
    return problems

"""История: тексты всех карточек направления, `stories/<k>.json` (ARCHITECTURE §3, «Узел story»;
REQUIREMENTS DR-12, CR-07, CR-11).

Историю собирает код из ответа писателя (`carousel/free_story.py`), а читают её все шаги за story:
visuals, directions, repair, checks. Инварианты, которым нужны пост и производный план, держит
связанная схема `bound_to`: она держит форму. Сведения и повторы мерят проверки `units` и
`repeats` после рендера, а не ворота: свободный текст не обязан повторять пост дословно (CR-11).
"""

from __future__ import annotations

from collections.abc import Iterator, Sequence
from typing import Self

from pydantic import model_validator

from carousel.cards import CardFace
from carousel.checks.results import TextCaps
from carousel.checks.text import check_leaks, check_numbers
from carousel.ideas import StructureAxis, ToneAxis
from carousel.plan import ROLES, Plan, Role
from carousel.schemas import (
    Contract,
    PostDoc,
    Text,
    anchor_problems,
)
from carousel.validation import summarize

# Материал поста нужен каждой карточке; количество само интерес не доказывает (CR-11).
UNIT_FLOORS: dict[Role, int] = dict.fromkeys(ROLES, 1)

# Раскладки по ролям: обложка и финал — свои слоты рамки, остальным они не нужны.
COVER_LAYOUT = "cover"
CLOSING_LAYOUT = "closing"


class StoryAxes(Contract):
    """Подача по двум осям, которые решает писатель: структура и тон (§2.4). Образ и материал —
    у арт-директора."""

    structure: StructureAxis
    tone: ToneAxis


class StoryCard(CardFace):
    """Карточка истории: роль, раскладка и элементы с текстом.

    Тексты класса `retell` держат якорь, служебные идут без якоря (FR-14). Картинки здесь нет:
    её решает арт-директор.
    """

    role: Role


def card_text(card: CardFace) -> str:
    """Весь текст карточки одной строкой: так сверяются проверки содержания."""
    return "\n".join(text for _, text in card.texts())


class Story(Contract):
    """История направления: сквозная линия, подача, карточки, объяснение для автора."""

    through_line: Text
    axes: StoryAxes
    cards: list[StoryCard]
    rationale: Text

    def anchors(self) -> Iterator[tuple[str, str]]:
        for number, card in enumerate(self.cards):
            for field, anchor in card.anchors():
                yield f"cards[{number}].{field}", anchor

    @classmethod
    def bound_to(
        cls,
        post: PostDoc,
        plan: Plan,
        *,
        text_caps: TextCaps = "warn",
    ) -> type[Self]:
        """Схема истории для этого плана: карточек и ролей столько же, раскладка обложки и финала на
        месте, якоря дословно из поста. В режиме `hard` текст ещё проходит потолки нагрузки."""

        class Bound(cls):  # type: ignore[valid-type, misc]
            __doc__ = cls.__doc__  # описание схемы берётся из докстринга, а он не наследуется

            @model_validator(mode="after")
            def _follows_the_plan(self) -> Self:
                problems = _shape_problems(self.cards, plan)
                if not problems:
                    found = anchor_problems(post.to_markdown(), self.anchors())
                    problems += [f"{p.field}: {p.verdict} ({p.detail})" for p in found]
                if not problems and text_caps == "hard":
                    problems += [
                        *check_numbers(self.cards, [beat.role for beat in plan.beats]).problems(),
                        *check_leaks(self.cards).problems(),
                    ]
                if problems:
                    raise ValueError(summarize(problems))
                return self

        Bound.__name__ = Bound.__qualname__ = cls.__name__
        return Bound


# --- проверки ----------------------------------------------------------------------------------


def _shape_problems(cards: Sequence[StoryCard], plan: Plan) -> list[str]:
    if len(cards) != plan.count:
        return [f"карточек: нужно {plan.count} по плану, в истории {len(cards)}"]
    problems: list[str] = []
    for number, (card, beat) in enumerate(zip(cards, plan.beats, strict=True), 1):
        if card.role != beat.role:
            problems.append(f"карточка {number}: роль {card.role}, а в плане {beat.role}")
        if beat.role == "cover" and card.layout != COVER_LAYOUT:
            problems.append(f"карточка {number}: обложка в раскладке {COVER_LAYOUT}")
        if beat.role == "finale" and card.layout != CLOSING_LAYOUT:
            problems.append(f"карточка {number}: финал в раскладке {CLOSING_LAYOUT}")
        if beat.role not in ("cover", "finale") and card.layout in (COVER_LAYOUT, CLOSING_LAYOUT):
            problems.append(f"карточка {number}: раскладка {card.layout} только у обложки и финала")
    return problems


def floor_problems(cards: Sequence[tuple[Role, CardFace]], floors: dict[Role, int]) -> list[str]:
    """Карточки ниже пола сведений своей роли (CR-11): пары «роль, карточка» по порядку.

    Их ищет проверка `units`: роль карточки спеки берётся из плана.
    """
    problems: list[str] = []
    for number, (role, card) in enumerate(cards, 1):
        units, floor = card.units(), floors.get(role, 1)
        if units < floor:
            problems.append(f"карточка {number}: сведений {units} из {floor}, роль {role}")
    return problems


def repeated_anchors(cards: Sequence[CardFace]) -> list[tuple[int, int, str]]:
    """Один якорь на двух карточках, кроме возврата финала к обложке (CR-04, CR-11).

    Тройка: номер ранней карточки, номер поздней (с единицы) и якорь. Их ищет проверка `repeats`.
    """
    found: list[tuple[int, int, str]] = []
    for later in range(1, len(cards)):
        for earlier in range(later):
            if later == len(cards) - 1 and earlier == 0:
                continue  # финал возвращается к цифре обложки
            shared = [
                a
                for a in cards[earlier].distinct_anchors()
                for b in cards[later].distinct_anchors()
                if a in b or b in a
            ]
            if shared:
                found.append((earlier + 1, later + 1, shared[0]))
    return found

"""Свободный писатель: ответ, сборка карточек и производный план (ARCHITECTURE §3, «Узел story»;
REQUIREMENTS DR-11, DR-12, CR-07, FR-30).

Писатель одним вызовом пишет карусель слота: заголовок и короткие абзацы на карточку, цифру или
цитату, когда они нужны, и пометку роли для оформления. Всё, что требует поста, находит код после
ответа: раскладку, элементы, якоря и тезисы, на которые опирается текст. Производный `Plan`
описывает написанное и ничего не требует. Ни сети, ни библиотек графа.
"""

from __future__ import annotations

import re
from collections.abc import Sequence
from difflib import SequenceMatcher
from typing import Self

from pydantic import field_validator, model_validator

from carousel.cards import (
    CardFace,
    Layout,
    Metric,
    MetricsElement,
    ParagraphElement,
    QuoteElement,
    TextClass,
    TitleElement,
    normalized,
)
from carousel.checks.quotes import normalize, significant_length
from carousel.ideas import StructureAxis, ToneAxis
from carousel.plan import (
    DEFAULT_PICTURE_SHARE,
    Beat,
    Plan,
    Role,
    count_problems,
    picture_problems,
    role_problems,
)
from carousel.schemas import (
    MIN_ANCHOR_LENGTH,
    STRONG_THESIS,
    Analysis,
    CardLimits,
    Contract,
    PostDoc,
    Text,
    anchor_problems,
)
from carousel.story import CLOSING_LAYOUT, COVER_LAYOUT, Story, StoryAxes, StoryCard
from carousel.validation import summarize

MAX_PARAGRAPHS = 3  # коротких абзацев на карточке (DR-12)
CONTENT_WORD = 4  # букв и цифр: слово короче одного не делает фрагмент поста сведением
PLACE_WORDS = 4  # слов поста вокруг цифры, которыми называется её место

_SENTENCE_END = (".", "!", "?")


class FreeFigure(Contract):
    """Одна крупная цифра карточки: значение дословно из поста и подпись к нему."""

    value: Text
    label: Text


class FreeQuote(Contract):
    """Цитата карточки: слова поста дословно и кто их сказал."""

    text: Text
    source: Text


class FreeCard(Contract):
    """Карточка в ответе писателя.

    `body` — от одного до трёх коротких абзацев. Цифра или цитата, не обе сразу. `role` — пометка
    для оформления из закрытого списка, `job` — что карточка даёт читателю, одной фразой,
    `picture` — нужна ли ей картинка.
    """

    title: Text
    body: list[Text]
    figure: FreeFigure | None
    quote: FreeQuote | None
    role: Role
    job: Text
    picture: bool

    @field_validator("body")
    @classmethod
    def _one_to_three_paragraphs(cls, value: list[str]) -> list[str]:
        if not 1 <= len(value) <= MAX_PARAGRAPHS:
            raise ValueError(f"абзацев от 1 до {MAX_PARAGRAPHS}, получено {len(value)}")
        return value

    @model_validator(mode="after")
    def _figure_or_quote(self) -> Self:
        if self.figure is not None and self.quote is not None:
            raise ValueError("на карточке одна цифра или одна цитата, не обе сразу")
        return self


class FreeStory(Contract):
    """Карусель слота в ответе писателя: сквозная линия, подача, объяснение автору и карточки.

    `through_line` держит карточки вместе, `structure` и `tone` называют подачу, `rationale`
    объясняет автору, почему карусель такая.
    """

    through_line: Text
    structure: StructureAxis
    tone: ToneAxis
    rationale: Text
    cards: list[FreeCard]

    @classmethod
    def bound_to(
        cls,
        post: PostDoc,
        limits: CardLimits,
        *,
        picture_share: float = DEFAULT_PICTURE_SHARE,
    ) -> type[Self]:
        """Схема ответа для этого поста: число карточек в лимитах, обложка и финал на местах,
        картинка у обложки и доля картинок в пределе, цифры и цитаты дословно из поста (CR-07)."""

        class Bound(cls):  # type: ignore[valid-type, misc]
            __doc__ = cls.__doc__  # описание схемы берётся из докстринга, а он не наследуется

            @model_validator(mode="after")
            def _fits_the_post(self) -> Self:
                problems = count_problems(len(self.cards), limits)
                if not problems:
                    problems += role_problems([card.role for card in self.cards])
                    problems += picture_problems([card.picture for card in self.cards], picture_share)
                    problems += _grounding_problems(self.cards, post)
                if problems:
                    raise ValueError(summarize(problems))
                return self

        Bound.__name__ = Bound.__qualname__ = cls.__name__
        return Bound

    def to_story(self, post: PostDoc) -> Story:
        """Карточки истории: раскладка по содержанию, элементы по порядку, якоря и класс текста
        находит код сопоставлением с постом (CR-07, FR-14)."""
        source = normalize(post.to_markdown())
        return Story(
            through_line=self.through_line,
            axes=StoryAxes(structure=self.structure, tone=self.tone),
            cards=[
                _story_card(card, _layout(number, len(self.cards), card), source)
                for number, card in enumerate(self.cards)
            ],
            rationale=self.rationale,
        )

    def to_plan(self, story: Story, analysis: Analysis) -> Plan:
        """План, описывающий написанное: роль, работа и картинка из ответа, тезисы, чей якорь перекрыл
        якорь карточки, и сильные тезисы, которых не несёт ни одна карточка (DR-11, CR-10)."""
        beats = [
            Beat(
                role=card.role,
                job=card.job,
                carries=_carried(analysis, face),
                picture=card.picture,
            )
            for card, face in zip(self.cards, story.cards, strict=True)
        ]
        carried = {number for beat in beats for number in beat.carries}
        left = [
            number
            for number, thesis in enumerate(analysis.theses)
            if thesis.strength >= STRONG_THESIS and number not in carried
        ]
        return Plan(
            reason=self.rationale,
            bridge=self.cards[-1].job,
            left_for_post=left,
            beats=beats,
        )


# --- проверка ответа ---------------------------------------------------------------------------


def _grounding_problems(cards: Sequence[FreeCard], post: PostDoc) -> list[str]:
    """Цифры и цитаты стоят в посте дословно (CR-07): остальной текст писатель пишет свободно."""
    markdown = post.to_markdown()
    source = normalize(markdown)
    problems = [
        f"карточка {number}: цифра «{card.figure.value}» не стоит в посте дословно"
        for number, card in enumerate(cards, 1)
        if card.figure is not None and normalize(card.figure.value) not in source
    ]
    quotes = [
        (f"карточка {number}: цитата", card.quote.text)
        for number, card in enumerate(cards, 1)
        if card.quote is not None
    ]
    problems += [
        f"{found.field}: {found.verdict} ({found.detail})"
        for found in anchor_problems(markdown, quotes)
    ]
    return problems


# --- сборка карточек ---------------------------------------------------------------------------


def _layout(number: int, count: int, card: FreeCard) -> Layout:
    if number == 0:
        return COVER_LAYOUT
    if number == count - 1:
        return CLOSING_LAYOUT
    if card.quote is not None:
        return "quote"
    return "numbers" if card.figure is not None else "text"


def _story_card(card: FreeCard, layout: Layout, source: str) -> StoryCard:
    elements: list[object] = [_words(TitleElement, "title", card.title, source)]
    if card.figure is not None:
        elements.append(
            MetricsElement(
                kind="metrics",
                items=[Metric(value=card.figure.value, label=card.figure.label)],
                anchors=[place_of(normalize(card.figure.value), source)],
            )
        )
    if card.quote is not None:
        elements.append(QuoteElement(kind="quote", text=card.quote.text, source=card.quote.source))
    elements += [_paragraph(text, source) for text in card.body]
    return StoryCard.model_validate({"role": card.role, "layout": layout, "elements": elements})


def _words(
    element: type[TitleElement], kind: str, text: str, source: str
) -> TitleElement:
    anchors = find_fragments(text, source)
    return element(
        kind="title", text=text, text_class=_text_class(anchors), anchors=anchors
    )


def _paragraph(text: str, source: str) -> ParagraphElement:
    anchors = find_fragments(text, source)
    return ParagraphElement(
        kind="paragraph", text=text, text_class=_text_class(anchors), anchors=anchors, emphasis=[]
    )


def _text_class(anchors: Sequence[str]) -> TextClass:
    """Есть общие с постом куски — пересказ, нет — служебный текст (FR-14)."""
    return "retell" if anchors else "service"


def find_fragments(text: str, source: str) -> list[str]:
    """Куски `text`, которые стоят в `source` дословно, в порядке текста.

    Кусок целыми словами, не короче `MIN_ANCHOR_LENGTH` знаков, с хотя бы одним словом длиннее трёх
    букв: так общие «в том, что» не становятся сведением. Находит сначала самый длинный общий кусок,
    затем то же слева и справа от него. `source` — пост после `normalize`.
    """
    text = normalize(text)
    matcher = SequenceMatcher(None, source, text, autojunk=False)
    found: list[tuple[int, str]] = []
    _collect(text, source, matcher, 0, len(text), found)
    return [fragment for _, fragment in sorted(found)]


def _collect(
    text: str,
    source: str,
    matcher: SequenceMatcher[str],
    low: int,
    high: int,
    found: list[tuple[int, str]],
) -> None:
    if high - low < MIN_ANCHOR_LENGTH:
        return
    match = matcher.find_longest_match(0, len(source), low, high)
    if match.size < MIN_ANCHOR_LENGTH:
        return
    start, end = match.b, match.b + match.size
    fragment = _whole_words(text, source, start, end, match.a)
    if fragment is not None and _substantial(fragment):
        found.append((start, fragment))
    _collect(text, source, matcher, low, start, found)
    _collect(text, source, matcher, end, high, found)


def _whole_words(text: str, source: str, start: int, end: int, at: int) -> str | None:
    """Общий кусок, обрезанный до границ слов: слово в тексте и в источнике целое."""
    size = end - start
    if (start > 0 and text[start - 1].isalnum()) or (at > 0 and source[at - 1].isalnum()):
        while start < end and text[start].isalnum():
            start += 1
            at += 1
    after = at + (end - start)
    if (end < len(text) and text[end].isalnum()) or (
        after < len(source) and source[after].isalnum()
    ):
        while end > start and text[end - 1].isalnum():
            end -= 1
    return text[start:end].strip() if end - start <= size else None


def _substantial(fragment: str) -> bool:
    if significant_length(fragment) < MIN_ANCHOR_LENGTH:
        return False
    return any(sum(char.isalnum() for char in word) >= CONTENT_WORD for word in fragment.split())


def place_of(value: str, source: str) -> str:
    """Место значения в источнике: оно с ближайшими словами в пределах предложения. Так цифре
    находится якорь, а не одно значение вроде «61%», короче минимума (FR-14)."""
    at = source.find(value)
    if at == -1:
        return value
    spans = [(m.start(), m.end()) for m in re.finditer(r"\S+", source)]
    first = next(n for n, (_, stop) in enumerate(spans) if stop > at)
    last = next(n for n, (begin, _) in enumerate(spans) if begin >= at + len(value)) - 1
    last = max(first, last) if last >= first else first
    for words, stop_at_sentence in ((PLACE_WORDS, True), (PLACE_WORDS * 2, False)):
        low, high = first, last
        while low > 0 and first - low < words and not (
            stop_at_sentence and source[spans[low - 1][0] : spans[low - 1][1]].endswith(_SENTENCE_END)
        ):
            low -= 1
        while high < len(spans) - 1 and high - last < words and not (
            stop_at_sentence and source[spans[high][0] : spans[high][1]].endswith(_SENTENCE_END)
        ):
            high += 1
        place = source[spans[low][0] : spans[high][1]]
        if significant_length(place) >= MIN_ANCHOR_LENGTH:
            return place
    return place


def _carried(analysis: Analysis, face: CardFace) -> list[int]:
    """Номера тезисов, чей якорь лежит в якоре карточки или наоборот."""
    anchors = face.distinct_anchors()
    return [
        number
        for number, thesis in enumerate(analysis.theses)
        if any(
            normalized(thesis.anchor) in anchor or anchor in normalized(thesis.anchor)
            for anchor in anchors
        )
    ]

